Object.assign(window.SB_FEED_BODY, {"pl-forum":{"src":"act:forum","route":"#/atlas/honey/forum","cta":"Open the Roman Forum","title":"Act III · The Roman Forum","body":"21 stops on this road, from “in- / im- / il- / ir- (not / without)” to “Agent Suffixes: -er / -or / -ist / -ian / -eur / -eer”."},"li-u24":{"src":"concept:19:concept","route":"#/stop/u24","cta":"Open this stop","title":"in- / im- / il- / ir- (not / without)","body":"Latin in- = not. It assimilates — changes shape — to match whatever consonant follows. This doubling is both a spelling signal and a meaning signal: the doubled letter reveals the hidden prefix."},"lc-u24-0":{"src":"concept:19:cards:0","route":"#/stop/u24","cta":"Open this stop","title":"in- / im- / il- / ir- (not / without) · The Assimilation Rule","body":"in- = not. Before l → il-: illegal, illegible, illicit. Before m/b/p → im-: impossible, immoral, impeccable. Before r → ir-: irregular, irrefutable, irrevocable. Before everything else → in-: insane, inimical, inexorable. The doubled first letter of the root IS the spelling signal."},"lc-u24-1":{"src":"concept:19:cards:1","route":"#/stop/u24","cta":"Open this stop","title":"in- / im- / il- / ir- (not / without) · High-Value im- Words","body":"Impeccable (im- + pecca = sin) = without flaw. Imperturbable = cannot be disturbed. Impecunious (im- + pecunia = money) = penniless. Impetuous = without restraint, rash. Implacable (im- + placare = appease) = cannot be calmed or satisfied. Each carries \"not/without\" into rich vocabulary."},"lc-u24-2":{"src":"concept:19:cards:2","route":"#/stop/u24","cta":"Open this stop","title":"in- / im- / il- / ir- (not / without) · High-Value in- Words","body":"Inexorable (in- + exorare = beg out of) = cannot be moved by pleading = relentless. Inimical (in- + amicus = friend) = not friendly = hostile. Inscrutable = cannot be understood. Innuendo (in- + nuendo = nodding toward) = an indirect suggestion. Ineffable = too great to express in words."},"lc-u24-3":{"src":"concept:19:cards:3","route":"#/stop/u24","cta":"Open this stop","title":"in- / im- / il- / ir- (not / without) · il- and ir- Words","body":"Illicit (il- + licitus = allowed) = not permitted. ⚠️ Confusable with elicit (to draw out) — completely different word! Illusory = not real. Irascible = quickly angered. Irreverent = not respectful. Irremediable = cannot be fixed. Irrevocable = cannot be called back."},"lc-u24-4":{"src":"concept:19:cards:4","route":"#/stop/u24","cta":"Open this stop","title":"in- / im- / il- / ir- (not / without) · The Dangerous Exception","body":"in- can ALSO mean \"into/toward\" (not just \"not\"): inflammable = catches fire easily — NOT fireproof! Invaluable = so valuable it cannot be measured = priceless, NOT worthless. Context and origin tell you which. When uncertain: get the definition before spelling."},"uq-u24-0":{"src":"unit:u24:qs:0","route":"#/stop/u24","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “in- / im- / il- / ir- (not / without)”?","opts":["Latin in- = not.","Five Greek prefixes of size and distance — from \"self\" to \"far,\" from \"tiny\" to \"enormous.\" These appear in science, technology, and everyday vocabulary.","Greek logos = word/reason/study.","Greek skopein = to look at."],"after":"From “in- / im- / il- / ir- (not / without)”."}},"uq-u24-1":{"src":"unit:u24:qs:1","route":"#/stop/u24","cta":"Open this stop","title":"Which belongs?","play":{"q":"Which word belongs to this chapter's family?","opts":["impeccable","chocolate","diaphanous","antipathy"],"after":"From “in- / im- / il- / ir- (not / without)”."}},"uq-u24-3":{"src":"unit:u24:qs:3","route":"#/stop/u24","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ has no PECCADILLO — peccABLE means 'can sin,' so ▁▁▁ means flawless.” — which word is this hook about?","opts":["impeccable","imperturbable","impecunious","impetuous"],"after":"From “in- / im- / il- / ir- (not / without)”."}},"wd-impeccable":{"src":"concept:19:words:0:def","route":"#/word/impeccable","cta":"Open the word card","title":"impeccable","roman":"ih-m-p-EH-k-uh-b-uh-l","body":"faultless or flawless","clip":1},"wx-impeccable":{"src":"concept:19:words:0:ex","route":"#/word/impeccable","cta":"Open the word card","title":"In a sentence · impeccable","body":"The young chef presented a dish with impeccable attention to detail, each garnish placed so precisely and every flavor so perfectly balanced that the judges sat in stunned, appreciative silence.","clip":1},"wh-impeccable":{"src":"concept:19:words:0:hook","route":"#/word/impeccable","cta":"Open the word card","title":"Remember it · impeccable","body":"ImPECCAble has no PECCADILLO — peccABLE means 'can sin,' so imPECCAble means flawless."},"wo-impeccable":{"src":"lore:impeccable:0","route":"#/word/impeccable","cta":"Open the word card","title":"Where it comes from · impeccable","body":"Latin peccare = to sin, to err"},"wd-impecunious":{"src":"concept:19:words:2:def","route":"#/word/impecunious","cta":"Open the word card","title":"impecunious","roman":"im-puh-KYOO-nee-us","body":"not having enough money to pay for necessities","clip":1},"wx-impecunious":{"src":"concept:19:words:2:ex","route":"#/word/impecunious","cta":"Open the word card","title":"In a sentence · impecunious","body":"The impecunious student survived on peanut butter sandwiches because he could barely afford groceries after paying rent.","clip":1},"wh-impecunious":{"src":"concept:19:words:2:hook","route":"#/word/impecunious","cta":"Open the word card","title":"Remember it · impecunious","body":"IMPECUNious means no PECUNIA (money) — a PECULIAR person with no PECUN-iary funds spells it with -IOUS, not -EOUS."},"wo-impecunious":{"src":"lore:impecunious:0","route":"#/word/impecunious","cta":"Open the word card","title":"Where it comes from · impecunious","body":"Latin im = not + pecunia = money"},"wd-impetuous":{"src":"concept:19:words:3:def","route":"#/word/impetuous","cta":"Open the word card","title":"impetuous","roman":"ih-m-p-EH-ch-w-uh-s","body":"characterized by sudden or rash action","clip":1},"wx-impetuous":{"src":"concept:19:words:3:ex","route":"#/word/impetuous","cta":"Open the word card","title":"In a sentence · impetuous","body":"One impetuous jump into the freezing lake left Ravi shivering and laughing at once.","clip":1},"wh-impetuous":{"src":"concept:19:words:3:hook","route":"#/word/impetuous","cta":"Open the word card","title":"Remember it · impetuous","body":"Impetuous behavior is full of force — end with the full '-uous,' not just '-os.'"},"wo-impetuous":{"src":"lore:impetuous:0","route":"#/word/impetuous","cta":"Open the word card","title":"Where it comes from · impetuous","body":"Latin impetus = attack/force"},"wd-implacable":{"src":"concept:19:words:4:def","route":"#/word/implacable","cta":"Open the word card","title":"implacable","roman":"ih-MPLA-kuh-buhl","body":"incapable of being placated","clip":1},"wx-implacable":{"src":"concept:19:words:4:ex","route":"#/word/implacable","cta":"Open the word card","title":"In a sentence · implacable","body":"The implacable storm battered the coast for three days, ignoring every weather forecaster's hope that it would weaken.","clip":1},"wh-implacable":{"src":"concept:19:words:4:hook","route":"#/word/implacable","cta":"Open the word card","title":"Remember it · implacable","body":"IM(not)+PLAC(placate)+ABLE: impossible to PLACATE"},"wo-implacable":{"src":"lore:implacable:0","route":"#/word/implacable","cta":"Open the word card","title":"Where it comes from · implacable","body":"Latin placare = to soothe, calm"},"wd-inexorable":{"src":"concept:19:words:5:def","route":"#/word/inexorable","cta":"Open the word card","title":"inexorable","roman":"ih-n-EH-k-s-ur-uh-b-uh-l","body":"unyielding or unalterable","clip":1},"wx-inexorable":{"src":"concept:19:words:5:ex","route":"#/word/inexorable","cta":"Open the word card","title":"In a sentence · inexorable","body":"No matter how many times the students begged for more time, the inexorable approach of the test deadline continued, and their teacher reminded them calmly that no extension would be granted.","clip":1},"wh-inexorable":{"src":"concept:19:words:5:hook","route":"#/word/inexorable","cta":"Open the word card","title":"Remember it · inexorable","body":"INEXORABLE ends in -ABLE — you'll NEVER be ABLE to beg your way to changing that ending."},"wo-inexorable":{"src":"lore:inexorable:0","route":"#/word/inexorable","cta":"Open the word card","title":"Where it comes from · inexorable","body":"Latin inexorabilis = not to be moved by prayer (orare = to pray)"},"wd-inimical":{"src":"concept:19:words:6:def","route":"#/word/inimical","cta":"Open the word card","title":"inimical","roman":"ih-NIH-mih-kuhl","body":"not friendly","clip":1},"wx-inimical":{"src":"concept:19:words:6:ex","route":"#/word/inimical","cta":"Open the word card","title":"In a sentence · inimical","body":"The freezing temperatures were inimical to the survival of the tropical plants left outside overnight.","clip":1},"wh-inimical":{"src":"concept:19:words:6:hook","route":"#/word/inimical","cta":"Open the word card","title":"Remember it · inimical","body":"INIMICal sounds like 'enemy'—because it means exactly that."},"wo-inimical":{"src":"lore:inimical:0","route":"#/word/inimical","cta":"Open the word card","title":"Where it comes from · inimical","body":"Latin inimicus = enemy (amicus = friend)"},"wd-inscrutable":{"src":"concept:19:words:7:def","route":"#/word/inscrutable","cta":"Open the word card","title":"inscrutable","roman":"ih-n-s-k-r-OO-t-uh-b-uh-l","body":"incapable of being investigated or analyzed","clip":1},"wx-inscrutable":{"src":"concept:19:words:7:ex","route":"#/word/inscrutable","cta":"Open the word card","title":"In a sentence · inscrutable","body":"Whiskers wore an inscrutable expression, and nobody could guess what the cat was plotting.","clip":1},"wh-inscrutable":{"src":"concept:19:words:7:hook","route":"#/word/inscrutable","cta":"Open the word card","title":"Remember it · inscrutable","body":"INSCRUTable cannot be SCRUtinized — find SCRU in both words and remember just one T."},"wo-inscrutable":{"src":"lore:inscrutable:0","route":"#/word/inscrutable","cta":"Open the word card","title":"Where it comes from · inscrutable","body":"Latin scrutari = to examine, search through"},"wd-innuendo":{"src":"concept:19:words:8:def","route":"#/word/innuendo","cta":"Open the word card","title":"innuendo","roman":"ih-n-y-oo-EH-n-d-oh","body":"an indirect intimation about a person usually of a derogatory nature","clip":1},"wx-innuendo":{"src":"concept:19:words:8:ex","route":"#/word/innuendo","cta":"Open the word card","title":"In a sentence · innuendo","body":"The rival candidate's speech was full of innuendo, hinting at wrongdoing without ever making a direct accusation.","clip":1},"wh-innuendo":{"src":"concept:19:words:8:hook","route":"#/word/innuendo","cta":"Open the word card","title":"Remember it · innuendo","body":"An INNUENDO sneaks IN with a nudge — double-N nudges you twice before you notice the hint."},"wo-innuendo":{"src":"lore:innuendo:0","route":"#/word/innuendo","cta":"Open the word card","title":"Where it comes from · innuendo","body":"Latin innuere = to nod toward, hint"},"wd-ineffable":{"src":"concept:19:words:9:def","route":"#/word/ineffable","cta":"Open the word card","title":"ineffable","roman":"ih-NEH-fuh-buhl","body":"defying expression or description","clip":1},"wx-ineffable":{"src":"concept:19:words:9:ex","route":"#/word/ineffable","cta":"Open the word card","title":"In a sentence · ineffable","body":"Standing at the edge of the Grand Canyon, Maya was struck by an ineffable sense of wonder she could not put into words.","clip":1},"wh-ineffable":{"src":"concept:19:words:9:hook","route":"#/word/ineffable","cta":"Open the word card","title":"Remember it · ineffable","body":"INEFFable feelings are too big to FABricate into words."},"wo-ineffable":{"src":"lore:ineffable:0","route":"#/word/ineffable","cta":"Open the word card","title":"Where it comes from · ineffable","body":"Latin ineffabilis = unutterable (fari = to speak)"},"wd-irascible":{"src":"concept:19:words:11:def","route":"#/word/irascible","cta":"Open the word card","title":"irascible","roman":"ih-r-A-s-ih-b-uh-l","body":"easily provoked to anger","clip":1},"wx-irascible":{"src":"concept:19:words:11:ex","route":"#/word/irascible","cta":"Open the word card","title":"In a sentence · irascible","body":"Our irascible neighbour grumbles whenever a football rolls into his tidy flower beds.","clip":1},"wh-irascible":{"src":"concept:19:words:11:hook","route":"#/word/irascible","cta":"Open the word card","title":"Remember it · irascible","body":"IRASCible people ERASE their calm in an instant of anger."},"wo-irascible":{"src":"lore:irascible:0","route":"#/word/irascible","cta":"Open the word card","title":"Where it comes from · irascible","body":"Latin irasci = to be angry (ira = anger, wrath)"},"wd-irrevocable":{"src":"concept:19:words:12:def","route":"#/word/irrevocable","cta":"Open the word card","title":"irrevocable","roman":"ih-REH-vuh-kuh-buhl","body":"incapable of being retracted or revoked","clip":1},"wx-irrevocable":{"src":"concept:19:words:12:ex","route":"#/word/irrevocable","cta":"Open the word card","title":"In a sentence · irrevocable","body":"Once the treaty was signed, the agreement was irrevocable, and neither country could back out without consequences.","clip":1},"wh-irrevocable":{"src":"concept:19:words:12:hook","route":"#/word/irrevocable","cta":"Open the word card","title":"Remember it · irrevocable","body":"Irrevocable: you cannot RE-VOKE (call back) the decision — it's gone forever."},"wo-irrevocable":{"src":"lore:irrevocable:0","route":"#/word/irrevocable","cta":"Open the word card","title":"Where it comes from · irrevocable","body":"Latin irrevocabilis, from ir-(not)+revocare(to call back)"},"wd-immutable":{"src":"concept:19:words:13:def","route":"#/word/immutable","cta":"Open the word card","title":"immutable","roman":"ih-MYOO-tuh-buhl","body":"not subject or susceptible to change or variation in form or quality or nature","clip":1},"wx-immutable":{"src":"concept:19:words:13:ex","route":"#/word/immutable","cta":"Open the word card","title":"In a sentence · immutable","body":"the view of that time was that all species were immutable, created by God","clip":1},"wh-immutable":{"src":"concept:19:words:13:hook","route":"#/word/immutable","cta":"Open the word card","title":"Remember it · immutable","body":"imMUTable has no E before -able because it CANNOT CHANGE its spelling — MUTe things don't speak up to add extra letters."},"wo-immutable":{"src":"lore:immutable:0","route":"#/word/immutable","cta":"Open the word card","title":"Where it comes from · immutable","body":"Latin mutare = to change"},"wd-incomprehensible":{"src":"concept:19:words:14:def","route":"#/word/incomprehensible","cta":"Open the word card","title":"incomprehensible","roman":"ih-ngkah-mpruh-HEH-nsih-buhl","body":"incapable of being explained or accounted for","clip":1},"wx-incomprehensible":{"src":"concept:19:words:14:ex","route":"#/word/incomprehensible","cta":"Open the word card","title":"In a sentence · incomprehensible","body":"The ancient manuscript was so damaged that its symbols were completely incomprehensible to even the most experienced historians.","clip":1},"wh-incomprehensible":{"src":"concept:19:words:14:hook","route":"#/word/incomprehensible","cta":"Open the word card","title":"Remember it · incomprehensible","body":"Can you HENS-ibly explain it? If not, it's incompreHENSible!"},"wo-incomprehensible":{"src":"lore:incomprehensible:0","route":"#/word/incomprehensible","cta":"Open the word card","title":"Where it comes from · incomprehensible","body":"Latin comprehendere = to grasp or seize"},"wd-indelible":{"src":"concept:19:words:15:def","route":"#/word/indelible","cta":"Open the word card","title":"indelible","roman":"ih-NDEH-lih-buhl","body":"cannot be removed or erased","clip":1},"wx-indelible":{"src":"concept:19:words:15:ex","route":"#/word/indelible","cta":"Open the word card","title":"In a sentence · indelible","body":"The vivid memories of that extraordinary summer trip to the mountains left an indelible impression on the young girl's mind, one so deeply engraved that she could still recall every color and smell decades later as an adult.","clip":1},"wh-indelible":{"src":"concept:19:words:15:hook","route":"#/word/indelible","cta":"Open the word card","title":"Remember it · indelible","body":"An inDELible mark won't let you DELETE it — keep 'del' from 'delete' in the middle."},"wo-indelible":{"src":"lore:indelible:0","route":"#/word/indelible","cta":"Open the word card","title":"Where it comes from · indelible","body":"Latin indelebilis = indestructible, from in+delere = to destroy/erase"},"wd-irrefutable":{"src":"concept:19:words:16:def","route":"#/word/irrefutable","cta":"Open the word card","title":"irrefutable","roman":"ih-ruh-FYOO-tuh-buhl","body":"impossible to deny or disprove","clip":1},"wx-irrefutable":{"src":"concept:19:words:16:ex","route":"#/word/irrefutable","cta":"Open the word card","title":"In a sentence · irrefutable","body":"Muddy paw prints across the sofa were irrefutable proof that Rex had climbed up.","clip":1},"wh-irrefutable":{"src":"concept:19:words:16:hook","route":"#/word/irrefutable","cta":"Open the word card","title":"Remember it · irrefutable","body":"IRREFUTable: no E before -able. The argument is so strong you cannot REFUTE it — ir+REFUT+able."},"wo-irrefutable":{"src":"lore:irrefutable:0","route":"#/word/irrefutable","cta":"Open the word card","title":"Where it comes from · irrefutable","body":"Latin in+refutare = not able to be refuted, from re+futare = to beat back"},"wd-illusory":{"src":"concept:19:words:17:def","route":"#/word/illusory","cta":"Open the word card","title":"illusory","roman":"ih-LOO-ser-ee","body":"based on or having the nature of an illusion","clip":1},"wx-illusory":{"src":"concept:19:words:17:ex","route":"#/word/illusory","cta":"Open the word card","title":"In a sentence · illusory","body":"Shimmering water on the hot road ahead proved illusory, vanishing as we drove closer.","clip":1},"wh-illusory":{"src":"concept:19:words:17:hook","route":"#/word/illusory","cta":"Open the word card","title":"Remember it · illusory","body":"ILLUSORY ends in -ory not -ary — the 'o' is the ghost letter that seems to disappear."},"wo-illusory":{"src":"lore:illusory:0","route":"#/word/illusory","cta":"Open the word card","title":"Where it comes from · illusory","body":"Latin illudere = to mock, play upon"},"li-u25":{"src":"concept:20:concept","route":"#/stop/u25","cta":"Open this stop","title":"un- (not / reverse action)","body":"Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs). The same two letters, two completely different jobs — word class determines meaning."},"lc-u25-0":{"src":"concept:20:cards:0","route":"#/stop/u25","cta":"Open this stop","title":"un- (not / reverse action) · Two Jobs","body":"un- before an adjective = \"not\": unkempt (not combed), unrequited (not returned), unprecedented (not before done). un- before a verb = \"reverse\": undo, unwrap, unravel. The same two letters — word class determines which meaning applies."},"lc-u25-1":{"src":"concept:20:cards:1","route":"#/stop/u25","cta":"Open this stop","title":"un- (not / reverse action) · High-Value un- Adjectives","body":"Unkempt (un- + kempt = combed). Unfettered (un- + fetter = chain) = not restrained. Unimpeachable = beyond reproach. Unscrupulous = without moral principles. Unwieldy = hard to handle. Unconscionable = shockingly unethical."},"lc-u25-2":{"src":"concept:20:cards:2","route":"#/stop/u25","cta":"Open this stop","title":"un- (not / reverse action) · Spelling Signal — Double-N","body":"When un- precedes a root starting with n, you get double-n: unnecessary = U-N-N-E-C-E-S-S-A-R-Y. Unnatural = U-N-N-A-T-U-R-A-L. Unnerve = U-N-N-E-R-V-E. The first n is the prefix; the second is the root. Not a doubling rule — just prefix meeting root."},"lc-u25-3":{"src":"concept:20:cards:3","route":"#/stop/u25","cta":"Open this stop","title":"un- (not / reverse action) · un- vs in-","body":"Both mean \"not\" but: un- is Old English/Germanic; in- is Latin. Unhappy (un- + Germanic). Infelicitous (in- + Latin felix = happy). The question \"What language does this word come from?\" at the microphone helps — Latin-origin words more often use in- negation, Germanic-origin words use un-."},"lc-u25-4":{"src":"concept:20:cards:4","route":"#/stop/u25","cta":"Open this stop","title":"un- (not / reverse action) · Classic Bee un- Words","body":"Unequivocal = not ambiguous. Unfathomable = cannot be fathomed/understood. Unprecedented = not before existing. Unrequited = love not returned. Unimpeachable = beyond any challenge. All negations of strong adjectives — and all with the simple, reliable U-N prefix."},"uq-u25-0":{"src":"unit:u25:qs:0","route":"#/stop/u25","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “un- (not / reverse action)”?","opts":["Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Five Greek prefixes of size and distance — from \"self\" to \"far,\" from \"tiny\" to \"enormous.\" These appear in science, technology, and everyday vocabulary.","Greek logos = word/reason/study.","Greek skopein = to look at."],"after":"From “un- (not / reverse action)”."}},"uq-u25-3":{"src":"unit:u25:qs:3","route":"#/stop/u25","cta":"Open this stop","title":"Whose hook?","play":{"q":"“KEMPT means combed — UN-kempt is the opposite of neat.” — which word is this hook about?","opts":["unkempt","unconscionable","unrequited","unprecedented"],"after":"From “un- (not / reverse action)”."}},"wd-unkempt":{"src":"concept:20:words:0:def","route":"#/word/unkempt","cta":"Open the word card","title":"unkempt","roman":"uh-n-k-EH-m-p-t","body":"disheveled or messy","clip":1},"wx-unkempt":{"src":"concept:20:words:0:ex","route":"#/word/unkempt","cta":"Open the word card","title":"In a sentence · unkempt","body":"After hiking for three days through the muddy forest trail without a mirror or comb, the explorer arrived at camp looking completely unkempt, with tangled hair and dirt-streaked clothes.","clip":1},"wh-unkempt":{"src":"concept:20:words:0:hook","route":"#/word/unkempt","cta":"Open the word card","title":"Remember it · unkempt","body":"KEMPT means combed — UN-kempt is the opposite of neat."},"wo-unkempt":{"src":"lore:unkempt:0","route":"#/word/unkempt","cta":"Open the word card","title":"Where it comes from · unkempt","body":"Old English cemban = to comb"},"wd-unconscionable":{"src":"concept:20:words:1:def","route":"#/word/unconscionable","cta":"Open the word card","title":"unconscionable","roman":"uh-n-k-AH-n-sh-uh-n-uh-b-uh-l","body":"means unscrupulous or not guided by conscience","clip":1},"wx-unconscionable":{"src":"concept:20:words:1:ex","route":"#/word/unconscionable","cta":"Open the word card","title":"In a sentence · unconscionable","body":"Charging lost hikers ten times the normal price for water is simply unconscionable.","clip":1},"wh-unconscionable":{"src":"concept:20:words:1:hook","route":"#/word/unconscionable","cta":"Open the word card","title":"Remember it · unconscionable","body":"UN + CONSCIENCE + ABLE: not able to be guided by conscience"},"wo-unconscionable":{"src":"lore:unconscionable:0","route":"#/word/unconscionable","cta":"Open the word card","title":"Where it comes from · unconscionable","body":"Latin conscientia = moral sense (con=with + scire=know)"},"wd-unrequited":{"src":"concept:20:words:2:def","route":"#/word/unrequited","cta":"Open the word card","title":"unrequited","roman":"uh-n-r-ee-k-w-AY-t-ih-d","body":"not returned or reciprocated","clip":1},"wx-unrequited":{"src":"concept:20:words:2:ex","route":"#/word/unrequited","cta":"Open the word card","title":"In a sentence · unrequited","body":"unrequited (unanswered) love","clip":1},"wh-unrequited":{"src":"concept:20:words:2:hook","route":"#/word/unrequited","cta":"Open the word card","title":"Remember it · unrequited","body":"QUIT has only one T — unreQUITed love means the other person QUIT on you without doubling their effort."},"wo-unrequited":{"src":"lore:unrequited:0","route":"#/word/unrequited","cta":"Open the word card","title":"Where it comes from · unrequited","body":"Old English un- = not + Old English cwitan = to pay back"},"wd-unprecedented":{"src":"concept:20:words:3:def","route":"#/word/unprecedented","cta":"Open the word card","title":"unprecedented","roman":"uh-NPREH-sih-deh-ntihd","body":"having no precedent; novel","clip":1},"wx-unprecedented":{"src":"concept:20:words:3:ex","route":"#/word/unprecedented","cta":"Open the word card","title":"In a sentence · unprecedented","body":"an unprecedented expansion in population and industry","clip":1},"wh-unprecedented":{"src":"concept:20:words:3:hook","route":"#/word/unprecedented","cta":"Open the word card","title":"Remember it · unprecedented","body":"unPRECEDented: no PRECEDE came before it — keep PRECE-D-E-N-T inside."},"wo-unprecedented":{"src":"lore:unprecedented:0","route":"#/word/unprecedented","cta":"Open the word card","title":"Where it comes from · unprecedented","body":"Latin praecedere = to go before"},"wd-unfettered":{"src":"concept:20:words:4:def","route":"#/word/unfettered","cta":"Open the word card","title":"unfettered","roman":"uh-NFEH-terd","body":"not bound by shackles and chains","clip":1},"wx-unfettered":{"src":"concept:20:words:4:ex","route":"#/word/unfettered","cta":"Open the word card","title":"In a sentence · unfettered","body":"With summer stretching ahead of her, Priya felt unfettered and free to pursue every creative project she had been dreaming about.","clip":1},"wh-unfettered":{"src":"concept:20:words:4:hook","route":"#/word/unfettered","cta":"Open the word card","title":"Remember it · unfettered","body":"UNFETTEREd — FETTERs are chains; double the T like tightening a shackle, then set it free with un-."},"wd-unimpeachable":{"src":"concept:20:words:5:def","route":"#/word/unimpeachable","cta":"Open the word card","title":"unimpeachable","roman":"uh-nih-MPEE-chuh-buhl","body":"beyond doubt or reproach","clip":1},"wx-unimpeachable":{"src":"concept:20:words:5:ex","route":"#/word/unimpeachable","cta":"Open the word card","title":"In a sentence · unimpeachable","body":"an unimpeachable source","clip":1},"wh-unimpeachable":{"src":"concept:20:words:5:hook","route":"#/word/unimpeachable","cta":"Open the word card","title":"Remember it · unimpeachable","body":"UNIMPEACHABLE ends in -ABLE not -IBLE — you ABLE-solutely cannot impeach a PEACH of a person."},"wo-unimpeachable":{"src":"lore:unimpeachable:0","route":"#/word/unimpeachable","cta":"Open the word card","title":"Where it comes from · unimpeachable","body":"Old French empeechier = to hinder, accuse"},"wd-unscrupulous":{"src":"concept:20:words:6:def","route":"#/word/unscrupulous","cta":"Open the word card","title":"unscrupulous","roman":"uh-NSKROO-pyuh-luhs","body":"without scruples or principles","clip":1},"wx-unscrupulous":{"src":"concept:20:words:6:ex","route":"#/word/unscrupulous","cta":"Open the word card","title":"In a sentence · unscrupulous","body":"unscrupulous politicos who would be happy to sell...their country in order to gain power","clip":1},"wh-unscrupulous":{"src":"concept:20:words:6:hook","route":"#/word/unscrupulous","cta":"Open the word card","title":"Remember it · unscrupulous","body":"UNSCRUPULOUS ends in -ULOUS—remember: a scrupULOUS person has scruples, an unscrupULOUS one does not."},"wo-unscrupulous":{"src":"lore:unscrupulous:0","route":"#/word/unscrupulous","cta":"Open the word card","title":"Where it comes from · unscrupulous","body":"Latin 'scrupulus' = small sharp stone, anxiety"},"wd-unwieldy":{"src":"concept:20:words:7:def","route":"#/word/unwieldy","cta":"Open the word card","title":"unwieldy","roman":"uh-NWEE-ldee","body":"difficult to use or handle or manage because of size or weight or shape","clip":1},"wx-unwieldy":{"src":"concept:20:words:7:ex","route":"#/word/unwieldy","cta":"Open the word card","title":"In a sentence · unwieldy","body":"we set about towing the unwieldy structure into the shelter","clip":1},"wh-unwieldy":{"src":"concept:20:words:7:hook","route":"#/word/unwieldy","cta":"Open the word card","title":"Remember it · unwieldy","body":"UNWIELDY: I before E — WIELD follows 'I before E' and that heavy thing is hard to carry."},"wo-unwieldy":{"src":"lore:unwieldy:0","route":"#/word/unwieldy","cta":"Open the word card","title":"Where it comes from · unwieldy","body":"Un- 'not' + Old English wieldan, 'to control, handle' — not handleable."},"wd-unnecessary":{"src":"concept:20:words:8:def","route":"#/word/unnecessary","cta":"Open the word card","title":"unnecessary","roman":"uh-NNEH-suh-seh-ree","body":"not necessary","clip":1},"wx-unnecessary":{"src":"concept:20:words:8:ex","route":"#/word/unnecessary","cta":"Open the word card","title":"In a sentence · unnecessary","body":"The teacher reminded students to avoid unnecessary details and stick to the main point.","clip":1},"wh-unnecessary":{"src":"concept:20:words:8:hook","route":"#/word/unnecessary","cta":"Open the word card","title":"Remember it · unnecessary","body":"Unnecessary has one C and double S — 'Not necessary: one C, two S's, please.'"},"wo-unnecessary":{"src":"lore:unnecessary:0","route":"#/word/unnecessary","cta":"Open the word card","title":"Where it comes from · unnecessary","body":"Latin 'necessarius' = unavoidable"},"wd-unnatural":{"src":"concept:20:words:9:def","route":"#/word/unnatural","cta":"Open the word card","title":"unnatural","roman":"uh-NNA-cher-uhl","body":"not in accordance with or determined by nature; contrary to nature","clip":1},"wx-unnatural":{"src":"concept:20:words:9:ex","route":"#/word/unnatural","cta":"Open the word card","title":"In a sentence · unnatural","body":"The eerie silence in the forest felt completely unnatural, as if every bird and creature had suddenly vanished, warning the hikers that something unusual and unsettling was lurking nearby.","clip":1},"wh-unnatural":{"src":"concept:20:words:9:hook","route":"#/word/unnatural","cta":"Open the word card","title":"Remember it · unnatural","body":"UN-natural has UN doubled up, just like something unnatural doubles up the oddness."},"wo-unnatural":{"src":"lore:unnatural:0","route":"#/word/unnatural","cta":"Open the word card","title":"Where it comes from · unnatural","body":"Old English 'naturu' = nature"},"wd-unnerve":{"src":"concept:20:words:10:def","route":"#/word/unnerve","cta":"Open the word card","title":"unnerve","roman":"uh-NURV","body":"disturb the composure of","clip":1},"wx-unnerve":{"src":"concept:20:words:10:ex","route":"#/word/unnerve","cta":"Open the word card","title":"In a sentence · unnerve","body":"The sudden crack of thunder was enough to unnerve even the bravest campers in the tent.","clip":1},"wh-unnerve":{"src":"concept:20:words:10:hook","route":"#/word/unnerve","cta":"Open the word card","title":"Remember it · unnerve","body":"UNNerve has double N — it takes NERVE to spell it with two N's without getting unnerved."},"wd-unequivocal":{"src":"concept:20:words:11:def","route":"#/word/unequivocal","cta":"Open the word card","title":"unequivocal","roman":"uh-nih-KWIH-vuh-kuhl","body":"admitting of no doubt or misunderstanding; having only one meaning or interpretation and leading to only one conclusion","clip":1},"wx-unequivocal":{"src":"concept:20:words:11:ex","route":"#/word/unequivocal","cta":"Open the word card","title":"In a sentence · unequivocal","body":"unequivocal evidence","clip":1},"wh-unequivocal":{"src":"concept:20:words:11:hook","route":"#/word/unequivocal","cta":"Open the word card","title":"Remember it · unequivocal","body":"UN-EQUI-VOC-AL: no equal VOICE (vox) — only one clear meaning; remember 'voc' like vocal."},"wo-unequivocal":{"src":"lore:unequivocal:0","route":"#/word/unequivocal","cta":"Open the word card","title":"Where it comes from · unequivocal","body":"Latin aequivocus = of equal voice/ambiguous (aequus=equal + vox=voice)"},"wd-unfathomable":{"src":"concept:20:words:12:def","route":"#/word/unfathomable","cta":"Open the word card","title":"unfathomable","roman":"uh-NFA-thuh-muh-buhl","body":"of depth; not capable of being sounded or measured","clip":1},"wx-unfathomable":{"src":"concept:20:words:12:ex","route":"#/word/unfathomable","cta":"Open the word card","title":"In a sentence · unfathomable","body":"Sailors lowered their weighted rope into unfathomable water and never touched the ocean floor.","clip":1},"wh-unfathomable":{"src":"concept:20:words:12:hook","route":"#/word/unfathomable","cta":"Open the word card","title":"Remember it · unfathomable","body":"UNFATHOMable depths — you can't FATHOM it; keep FATHOM and add -able, not -ible."},"wo-unfathomable":{"src":"lore:unfathomable:0","route":"#/word/unfathomable","cta":"Open the word card","title":"Where it comes from · unfathomable","body":"Old English faethm = outstretched arms, depth"},"wd-unmistakable":{"src":"concept:20:words:13:def","route":"#/word/unmistakable","cta":"Open the word card","title":"unmistakable","roman":"uh-nmih-STAY-kuh-buhl","body":"clearly evident to the mind","clip":1},"wx-unmistakable":{"src":"concept:20:words:13:ex","route":"#/word/unmistakable","cta":"Open the word card","title":"In a sentence · unmistakable","body":"his opposition to slavery was unmistakable","clip":1},"wh-unmistakable":{"src":"concept:20:words:13:hook","route":"#/word/unmistakable","cta":"Open the word card","title":"Remember it · unmistakable","body":"UNMISTAKABLE drops the E in MISTAKE before -ABLE — no E needed when it's that obvious."},"wo-unmistakable":{"src":"lore:unmistakable:0","route":"#/word/unmistakable","cta":"Open the word card","title":"Where it comes from · unmistakable","body":"Old Norse mistaka = to take in error"},"li-u26":{"src":"concept:21:concept","route":"#/stop/u26","cta":"Open this stop","title":"dis- (apart / not / opposite)","body":"Latin dis- = apart, not, or deprived of. When it meets a root beginning with s, the result is double-s. Recognizing this doubling is the key to spelling dissipate, dissolve, and dissemble correctly."},"lc-u26-0":{"src":"concept:21:cards:0","route":"#/stop/u26","cta":"Open this stop","title":"dis- (apart / not / opposite) · What dis- Does","body":"dis- = apart, not, or deprive of. Dissonance (dis- + sonus = sound apart) = harsh discord. Discern (dis- + cernere = separate) = separate truth from error. Disdain (dis- + dignare = deem worthy) = think something not worthy. Disparity = lack of equality. Dissemble = disguise one's true appearance."},"lc-u26-1":{"src":"concept:21:cards:1","route":"#/stop/u26","cta":"Open this stop","title":"dis- (apart / not / opposite) · dis- + s-root = double-s","body":"When the root begins with s, you get dis- + s- = diss-: dissipate (scatter apart), dissolve, dissent, dissertation, dissemble, disseminate (dis- + semen = seed = scatter seeds of ideas). The double-s is the dis- prefix meeting a root that starts with s."},"lc-u26-2":{"src":"concept:21:cards:2","route":"#/stop/u26","cta":"Open this stop","title":"dis- (apart / not / opposite) · Spellings That Trap","body":"Discernible = discern + -ible (use -ible because discern is from Latin — the stem cannot stand alone). Distraught = dis- + trahere = pulled apart = extremely upset — note the -aught from Old English. Disingenuous = dis- + in- + gen — two negating prefixes stacked."},"lc-u26-3":{"src":"concept:21:cards:3","route":"#/stop/u26","cta":"Open this stop","title":"dis- (apart / not / opposite) · dis- vs de-","body":"Both weaken or remove things. dis- = separation or absence. de- = removal or reversal. Disarm = remove the ability to use arms. Dearm = not a word. Disintegrate = fall apart. Decompose = break down chemically. Disagree = the opposite of agree."},"lc-u26-4":{"src":"concept:21:cards:4","route":"#/stop/u26","cta":"Open this stop","title":"dis- (apart / not / opposite) · High-Value dis- Words","body":"Disparage = speak with disdain. Dissonance = lack of harmony. Discrepancy = a gap between things. Disconcert = unsettle. Discomfit = defeat or thwart. ⚠️ Discomfit ≠ discomfort — discomfit means to defeat, not merely to make uncomfortable. A classic vocabulary-round distinction."},"uq-u26-3":{"src":"unit:u26:qs:3","route":"#/stop/u26","cta":"Open this stop","title":"Whose hook?","play":{"q":"“DIS-IN-GENU-OUS hides the Latin for 'genuine' — someone ▁▁▁ is NOT genuine.” — which word is this hook about?","opts":["disingenuous","discernible","distraught","dissipate"],"after":"From “dis- (apart / not / opposite)”."}},"wd-disingenuous":{"src":"concept:21:words:0:def","route":"#/word/disingenuous","cta":"Open the word card","title":"disingenuous","roman":"dih-sih-NJEH-nyoo-uhs","body":"not straightforward or candid; giving a false appearance of frankness","clip":1},"wx-disingenuous":{"src":"concept:21:words:0:ex","route":"#/word/disingenuous","cta":"Open the word card","title":"In a sentence · disingenuous","body":"an ambitious, disingenuous, philistine, and hypocritical operator, who...exemplified...the most disagreeable traits of his time","clip":1},"wh-disingenuous":{"src":"concept:21:words:0:hook","route":"#/word/disingenuous","cta":"Open the word card","title":"Remember it · disingenuous","body":"DIS-IN-GENU-OUS hides the Latin for 'genuine' — someone disingenuous is NOT genuine."},"wo-disingenuous":{"src":"lore:disingenuous:0","route":"#/word/disingenuous","cta":"Open the word card","title":"Where it comes from · disingenuous","body":"Latin dis- = not + ingenuus = freeborn, frank, candid"},"wd-discernible":{"src":"concept:21:words:1:def","route":"#/word/discernible","cta":"Open the word card","title":"discernible","roman":"d-ih-s-UR-n-uh-b-uh-l","body":"means capable of being distinguished","clip":1},"wx-discernible":{"src":"concept:21:words:1:ex","route":"#/word/discernible","cta":"Open the word card","title":"In a sentence · discernible","body":"things happen in the earth and sky with no discernible cause","clip":1},"wh-discernible":{"src":"concept:21:words:1:hook","route":"#/word/discernible","cta":"Open the word card","title":"Remember it · discernible","body":"DisCERNible ends in -IBLE not -ABLE — if it's discernible, you're ABLE to see it, but spell it with an 'i' because you use your EYE."},"wo-discernible":{"src":"lore:discernible:0","route":"#/word/discernible","cta":"Open the word card","title":"Where it comes from · discernible","body":"Latin discernere = to separate, distinguish"},"wd-dissipate":{"src":"concept:21:words:3:def","route":"#/word/dissipate","cta":"Open the word card","title":"dissipate","roman":"DIH-suh-payt","body":"to cause to separate and go in different directions","clip":1},"wx-dissipate":{"src":"concept:21:words:3:ex","route":"#/word/dissipate","cta":"Open the word card","title":"In a sentence · dissipate","body":"By noon, the morning fog had begun to dissipate, revealing a brilliant blue sky over the harbor.","clip":1},"wh-dissipate":{"src":"concept:21:words:3:hook","route":"#/word/dissipate","cta":"Open the word card","title":"Remember it · dissipate","body":"diSSIPate — watch it SLIP away like water you SIP that dribbles away."},"wo-dissipate":{"src":"lore:dissipate:0","route":"#/word/dissipate","cta":"Open the word card","title":"Where it comes from · dissipate","body":"Latin dissipare = to scatter, from dis-(apart)+supare(to throw)"},"wd-disseminate":{"src":"concept:21:words:4:def","route":"#/word/disseminate","cta":"Open the word card","title":"disseminate","roman":"dih-SEH-muh-nayt","body":"cause to become widely known","clip":1},"wx-disseminate":{"src":"concept:21:words:4:ex","route":"#/word/disseminate","cta":"Open the word card","title":"In a sentence · disseminate","body":"Health officials worked urgently to disseminate accurate information about the new vaccine to every community center, school, and local clinic across the entire region within one week.","clip":1},"wh-disseminate":{"src":"concept:21:words:4:hook","route":"#/word/disseminate","cta":"Open the word card","title":"Remember it · disseminate","body":"To disSEMinate is to scatter SEEDS widely — double S scatters the information like seeds in the wind."},"wo-disseminate":{"src":"lore:disseminate:0","route":"#/word/disseminate","cta":"Open the word card","title":"Where it comes from · disseminate","body":"Latin seminare = to sow, semen = seed"},"wd-dissonance":{"src":"concept:21:words:5:def","route":"#/word/dissonance","cta":"Open the word card","title":"dissonance","roman":"DIH-suh-nuhns","body":"a conflict of people's opinions or actions or characters","clip":1},"wx-dissonance":{"src":"concept:21:words:5:ex","route":"#/word/dissonance","cta":"Open the word card","title":"In a sentence · dissonance","body":"Dissonance between the two captains meant our team practised all week without a plan.","clip":1},"wh-dissonance":{"src":"concept:21:words:5:hook","route":"#/word/dissonance","cta":"Open the word card","title":"Remember it · dissonance","body":"DisSonance: two SONic clashes — the double 's' sounds like two notes scraping against each other."},"wo-dissonance":{"src":"lore:dissonance:0","route":"#/word/dissonance","cta":"Open the word card","title":"Where it comes from · dissonance","body":"Latin dis-(apart)+sonare(to sound)"},"wd-disparage":{"src":"concept:21:words:6:def","route":"#/word/disparage","cta":"Open the word card","title":"disparage","roman":"dih-SPEH-rihj","body":"express a negative opinion of","clip":1},"wx-disparage":{"src":"concept:21:words:6:ex","route":"#/word/disparage","cta":"Open the word card","title":"In a sentence · disparage","body":"She disparaged her student's efforts","clip":1},"wh-disparage":{"src":"concept:21:words:6:hook","route":"#/word/disparage","cta":"Open the word card","title":"Remember it · disparage","body":"To DISPARAGE is to put someone below your PAR — think of a golfer who trashes par, spelled -age at the end."},"wo-disparage":{"src":"lore:disparage:0","route":"#/word/disparage","cta":"Open the word card","title":"Where it comes from · disparage","body":"Old French parage = rank, lineage"},"wd-discrepancy":{"src":"concept:21:words:7:def","route":"#/word/discrepancy","cta":"Open the word card","title":"discrepancy","roman":"dih-SKREH-puh-nsee","body":"a difference between conflicting facts or claims or opinions","clip":1},"wx-discrepancy":{"src":"concept:21:words:7:ex","route":"#/word/discrepancy","cta":"Open the word card","title":"In a sentence · discrepancy","body":"A discrepancy between the two scoreboards forced the judges to count the goals again.","clip":1},"wh-discrepancy":{"src":"concept:21:words:7:hook","route":"#/word/discrepancy","cta":"Open the word card","title":"Remember it · discrepancy","body":"Hear the CREP-A-NCY: the A in discrepANcy marks the gap between the facts."},"wo-discrepancy":{"src":"lore:discrepancy:0","route":"#/word/discrepancy","cta":"Open the word card","title":"Where it comes from · discrepancy","body":"Latin discrepare = to sound differently"},"wd-disconcert":{"src":"concept:21:words:8:def","route":"#/word/disconcert","cta":"Open the word card","title":"disconcert","roman":"dih-skuh-NSURT","body":"cause to feel embarrassment","clip":1},"wx-disconcert":{"src":"concept:21:words:8:ex","route":"#/word/disconcert","cta":"Open the word card","title":"In a sentence · disconcert","body":"Loud applause in the middle of her poem seemed to disconcert Anya completely.","clip":1},"wh-disconcert":{"src":"concept:21:words:8:hook","route":"#/word/disconcert","cta":"Open the word card","title":"Remember it · disconcert","body":"DisCONCERT ruins a CONCERT — when musicians dis-agree, the concert falls apart!"},"wo-disconcert":{"src":"lore:disconcert:0","route":"#/word/disconcert","cta":"Open the word card","title":"Where it comes from · disconcert","body":"French disconcerter = to disturb, dis- + concerter = to concert/arrange"},"wd-discomfit":{"src":"concept:21:words:9:def","route":"#/word/discomfit","cta":"Open the word card","title":"discomfit","roman":"dis-KUM-fit","body":"cause to lose one's composure","clip":1},"wx-discomfit":{"src":"concept:21:words:9:ex","route":"#/word/discomfit","cta":"Open the word card","title":"In a sentence · discomfit","body":"The unexpected question seemed to discomfit the speaker, who fumbled nervously with his notes.","clip":1},"wh-discomfit":{"src":"concept:21:words:9:hook","route":"#/word/discomfit","cta":"Open the word card","title":"Remember it · discomfit","body":"DisCOMFIT ends in -FIT not -FORT — you are so un-FIT with discomfort that you discomFIT!"},"wo-discomfit":{"src":"lore:discomfit:0","route":"#/word/discomfit","cta":"Open the word card","title":"Where it comes from · discomfit","body":"Old French desconfit = defeated, undone"},"wd-dissemble":{"src":"concept:21:words:10:def","route":"#/word/dissemble","cta":"Open the word card","title":"dissemble","roman":"dih-SEH-mbuhl","body":"make believe with the intent to deceive","clip":1},"wx-dissemble":{"src":"concept:21:words:10:ex","route":"#/word/dissemble","cta":"Open the word card","title":"In a sentence · dissemble","body":"The spy had to dissemble perfectly, pretending to be a simple baker while gathering crucial information for her country.","clip":1},"wh-dissemble":{"src":"concept:21:words:10:hook","route":"#/word/dissemble","cta":"Open the word card","title":"Remember it · dissemble","body":"diSSEMble — to diSSEMble is to disSEMinate a false SEMBLANCE of yourself."},"wo-dissemble":{"src":"lore:dissemble:0","route":"#/word/dissemble","cta":"Open the word card","title":"Where it comes from · dissemble","body":"French dissimuler = to dissimulate, from Latin dissimulare = to disguise"},"wd-disparate":{"src":"concept:21:words:11:def","route":"#/word/disparate","cta":"Open the word card","title":"disparate","roman":"DIH-sper-iht","body":"fundamentally different or distinct in quality or kind","clip":1},"wx-disparate":{"src":"concept:21:words:11:ex","route":"#/word/disparate","cta":"Open the word card","title":"In a sentence · disparate","body":"The science fair attracted disparate projects ranging from solar-powered cars to studies on the psychology of color.","clip":1},"wh-disparate":{"src":"concept:21:words:11:hook","route":"#/word/disparate","cta":"Open the word card","title":"Remember it · disparate","body":"disPARate — remember PAR means equal, so disparate means NOT equal or alike."},"wo-disparate":{"src":"lore:disparate:0","route":"#/word/disparate","cta":"Open the word card","title":"Where it comes from · disparate","body":"Latin disparatus = separated, from dis-(apart)+parare(to prepare, arrange)"},"wd-disparity":{"src":"concept:21:words:12:def","route":"#/word/disparity","cta":"Open the word card","title":"disparity","roman":"dih-SPEH-ruh-tee","body":"inequality or difference in some respect","clip":1},"wx-disparity":{"src":"concept:21:words:12:ex","route":"#/word/disparity","cta":"Open the word card","title":"In a sentence · disparity","body":"The report highlighted a troubling disparity in test scores between students from wealthy and low-income schools.","clip":1},"wh-disparity":{"src":"concept:21:words:12:hook","route":"#/word/disparity","cta":"Open the word card","title":"Remember it · disparity","body":"DISPARITY hides PAR — when there's no PAR (equality), you have a DISPARITY; mind the A."},"wo-disparity":{"src":"lore:disparity:0","route":"#/word/disparity","cta":"Open the word card","title":"Where it comes from · disparity","body":"Latin disparitas = inequality, from par = equal"},"wd-dissolute":{"src":"concept:21:words:13:def","route":"#/word/dissolute","cta":"Open the word card","title":"dissolute","roman":"DIS-uh-loot","body":"unrestrained by convention or morality","clip":1},"wx-dissolute":{"src":"concept:21:words:13:ex","route":"#/word/dissolute","cta":"Open the word card","title":"In a sentence · dissolute","body":"The dissolute nobleman squandered his entire fortune on reckless gambling and extravagant midnight parties.","clip":1},"wh-dissolute":{"src":"concept:21:words:13:hook","route":"#/word/dissolute","cta":"Open the word card","title":"Remember it · dissolute","body":"A disSolute person is so loose they LOOSEn all rules — the double 's' is as unrestrained as they are."},"wo-dissolute":{"src":"lore:dissolute:0","route":"#/word/dissolute","cta":"Open the word card","title":"Where it comes from · dissolute","body":"Latin dis-(apart)+solvere(to loosen)"},"li-u27":{"src":"concept:22:concept","route":"#/stop/u27","cta":"Open this stop","title":"de- (down / away / reverse)","body":"Latin de- removes, reverses, takes down, or completely intensifies. It is one of the most stable Latin prefixes — it never assimilates. The challenge is always what comes after de-."},"lc-u27-0":{"src":"concept:22:cards:0","route":"#/stop/u27","cta":"Open this stop","title":"de- (down / away / reverse) · What de- Does","body":"de- removes (decaffeinate, defrost), reverses (decode, decompose), goes down (descend, decline), or means thoroughly (devout, demolish). Desiccate = de- + siccus (dry) = remove all moisture. Denouement (de- + French nouer = untie) = the final unraveling of a story's plot."},"lc-u27-1":{"src":"concept:22:cards:1","route":"#/stop/u27","cta":"Open this stop","title":"de- (down / away / reverse) · de- Removing Words","body":"Decimate = de- + decimus (tenth) = originally kill one in ten (Roman military punishment); now: destroy a large portion. Denigrate = de- + niger (black) = blacken someone's reputation. Deracinate = de- + radix (root) = uproot entirely. Denude = strip completely bare."},"lc-u27-2":{"src":"concept:22:cards:2","route":"#/stop/u27","cta":"Open this stop","title":"de- (down / away / reverse) · French de- Words","body":"Many French loanwords begin de-: Demesne (an estate's private land), Demitasse (demi = half + tasse = cup = small coffee cup), Débâcle (sudden collapse), Débonnaire/Debonair (from de bon aire = of good air = charming). The accent often disappears in English but the spelling stays."},"lc-u27-3":{"src":"concept:22:cards:3","route":"#/stop/u27","cta":"Open this stop","title":"de- (down / away / reverse) · de- vs dis-","body":"de- = reversal or removal; dis- = separation or absence. Decode = reverse the coding. Disagree = the opposite of agree. Defrost = remove frost. Disintegrate = fall apart. Both prefixes weaken or oppose — the nuance is direction vs absence."},"lc-u27-4":{"src":"concept:22:cards:4","route":"#/stop/u27","cta":"Open this stop","title":"de- (down / away / reverse) · Spelling Details","body":"Desiccate = D-E-S-I-C-C-A-T-E — the double-c is from the Latin siccare, not from prefix meeting root. Denouement = D-E-N-O-U-E-M-E-N-T (French -ou- vowel pair). Deign = D-E-I-G-N (silent g from Old French). Deft — de- here is part of an Old English root, not the Latin prefix."},"uq-u27-3":{"src":"unit:u27:qs:3","route":"#/stop/u27","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ has a double C—think of two C's squeezing all the moisture out” — which word is this hook about?","opts":["desiccate","decaffeinate","denouement","decimate"],"after":"From “de- (down / away / reverse)”."}},"wx-desiccate":{"src":"concept:22:words:0:ex","route":"#/word/desiccate","cta":"Open the word card","title":"In a sentence · desiccate","body":"Farmers desiccate mango slices in the hot sun so they keep all winter.","clip":1},"wh-desiccate":{"src":"concept:22:words:0:hook","route":"#/word/desiccate","cta":"Open the word card","title":"Remember it · desiccate","body":"DESICCATE has a double C—think of two C's squeezing all the moisture out"},"wo-desiccate":{"src":"lore:desiccate:0","route":"#/word/desiccate","cta":"Open the word card","title":"Where it comes from · desiccate","body":"Latin desiccare = to dry up, from de-(completely)+siccare(to dry)+siccus(dry)"},"wx-decaffeinate":{"src":"concept:22:words:1:ex","route":"#/word/decaffeinate","cta":"Open the word card","title":"In a sentence · decaffeinate","body":"The company uses a special water process to decaffeinate its coffee beans without altering the rich flavor.","clip":1},"wh-decaffeinate":{"src":"concept:22:words:1:hook","route":"#/word/decaffeinate","cta":"Open the word card","title":"Remember it · decaffeinate","body":"DECAFFEINATE has a DOUBLE F — think of two coffee beans being pulled out: de-CAFFEINE-ate!"},"wo-decaffeinate":{"src":"lore:decaffeinate:0","route":"#/word/decaffeinate","cta":"Open the word card","title":"Where it comes from · decaffeinate","body":"Arabic qahwah = coffee (via caffeine) + Latin de- = remove from"},"wd-denouement":{"src":"concept:22:words:2:def","route":"#/word/denouement","cta":"Open the word card","title":"denouement","roman":"d-ay-n-oo-m-AH-n","body":"the final outcome or resolution of a complex sequence of events, especially in a story","clip":1},"wx-denouement":{"src":"concept:22:words:2:ex","route":"#/word/denouement","cta":"Open the word card","title":"In a sentence · denouement","body":"In the thrilling denouement of the mystery novel, the detective revealed that the butler had hidden the stolen jewels in the clock.","clip":1},"wh-denouement":{"src":"concept:22:words:2:hook","route":"#/word/denouement","cta":"Open the word card","title":"Remember it · denouement","body":"The dénouement UNKNOTs the story — dé(undo)+noue(knot)"},"wo-denouement":{"src":"lore:denouement:0","route":"#/word/denouement","cta":"Open the word card","title":"Where it comes from · denouement","body":"French dénouer = to untie, from de-(undo)+nouer(to knot)"},"wd-decimate":{"src":"concept:22:words:3:def","route":"#/word/decimate","cta":"Open the word card","title":"decimate","roman":"DEH-suh-mayt","body":"to destroy or drastically reduce a large part of a group or amount","clip":1},"wx-decimate":{"src":"concept:22:words:3:ex","route":"#/word/decimate","cta":"Open the word card","title":"In a sentence · decimate","body":"A late frost decimated the apple orchard, leaving barely a tenth of the harvest.","clip":1},"wh-decimate":{"src":"concept:22:words:3:hook","route":"#/word/decimate","cta":"Open the word card","title":"Remember it · decimate","body":"Roman soldiers were DECIMATEd — one in ten chosen by FATE, spelled with just one 'm' and '-ate'."},"wo-decimate":{"src":"lore:decimate:0","route":"#/word/decimate","cta":"Open the word card","title":"Where it comes from · decimate","body":"Latin decimare = to take a tenth, from decimus = tenth"},"wd-denigrate":{"src":"concept:22:words:4:def","route":"#/word/denigrate","cta":"Open the word card","title":"denigrate","roman":"DEH-nuh-grayt","body":"to speak badly of someone or something, making them seem worthless","clip":1},"wx-denigrate":{"src":"concept:22:words:4:ex","route":"#/word/denigrate","cta":"Open the word card","title":"In a sentence · denigrate","body":"Do not denigrate Sam's painting just because your own drawing won the prize.","clip":1},"wh-denigrate":{"src":"concept:22:words:4:hook","route":"#/word/denigrate","cta":"Open the word card","title":"Remember it · denigrate","body":"To DENIGRATE is to blacken someone's name — spot 'nigr' (black, like Nigeria's name root) in the middle."},"wo-denigrate":{"src":"lore:denigrate:0","route":"#/word/denigrate","cta":"Open the word card","title":"Where it comes from · denigrate","body":"Latin denigrare = to blacken, from niger = black"},"wd-deracinate":{"src":"concept:22:words:5:def","route":"#/word/deracinate","cta":"Open the word card","title":"deracinate","roman":"dih-RAS-ih-nayt","body":"move (people) forcibly from their homeland into a new and foreign environment","clip":1},"wx-deracinate":{"src":"concept:22:words:5:ex","route":"#/word/deracinate","cta":"Open the word card","title":"In a sentence · deracinate","body":"A new dam deracinated the villagers, moving them far from the valley they loved.","clip":1},"wh-deracinate":{"src":"concept:22:words:5:hook","route":"#/word/deracinate","cta":"Open the word card","title":"Remember it · deracinate","body":"De-RACIN-ate: picture pulling a RACE of people out by the roots like a plant."},"wd-demesne":{"src":"concept:22:words:6:def","route":"#/word/demesne","cta":"Open the word card","title":"demesne","roman":"duh-MAYN","body":"the land around a large country house that its owner keeps for their own use","clip":1},"wx-demesne":{"src":"concept:22:words:6:ex","route":"#/word/demesne","cta":"Open the word card","title":"In a sentence · demesne","body":"Deer wandered freely across the lord's demesne, grazing right up to the manor windows.","clip":1},"wh-demesne":{"src":"concept:22:words:6:hook","route":"#/word/demesne","cta":"Open the word card","title":"Remember it · demesne","body":"A demesSNE is a lord's estate — the tricky SNE at the end is SILENT, like a secret domain."},"wo-demesne":{"src":"lore:demesne:0","route":"#/word/demesne","cta":"Open the word card","title":"Where it comes from · demesne","body":"Old French demeine = domain, from Latin dominium = lordship"},"wd-demitasse":{"src":"concept:22:words:7:def","route":"#/word/demitasse","cta":"Open the word card","title":"demitasse","roman":"DEM-ee-tas","body":"a small cup for serving strong black coffee","clip":1},"wx-demitasse":{"src":"concept:22:words:7:ex","route":"#/word/demitasse","cta":"Open the word card","title":"In a sentence · demitasse","body":"After dinner, the host offered each guest a demitasse of thick, fragrant espresso.","clip":1},"wh-demitasse":{"src":"concept:22:words:7:hook","route":"#/word/demitasse","cta":"Open the word card","title":"Remember it · demitasse","body":"A DEMITASSE is a DEMI (half) cup with a TASSE (cup) — double S in tasse, like the strong espresso gives you a double kick."},"wo-demitasse":{"src":"lore:demitasse:0","route":"#/word/demitasse","cta":"Open the word card","title":"Where it comes from · demitasse","body":"French demi = half + tasse = cup"},"wd-debacle":{"src":"concept:22:words:8:def","route":"#/word/debacle","cta":"Open the word card","title":"debacle","roman":"duh-BAH-kuhl","body":"a sudden and violent collapse","clip":1},"wx-debacle":{"src":"concept:22:words:8:ex","route":"#/word/debacle","cta":"Open the word card","title":"In a sentence · debacle","body":"The school play turned into a complete debacle when the backdrop fell, the microphones cut out, and the lead forgot every line.","clip":1},"wh-debacle":{"src":"concept:22:words:8:hook","route":"#/word/debacle","cta":"Open the word card","title":"Remember it · debacle","body":"A DEBACLE has no K — think of ice suddenly cracking: dé-BA-CLE, smooth and French, no clunky K."},"wd-debonair":{"src":"concept:22:words:9:def","route":"#/word/debonair","cta":"Open the word card","title":"debonair","roman":"deh-buh-NEHR","body":"having a sophisticated charm","clip":1},"wx-debonair":{"src":"concept:22:words:9:ex","route":"#/word/debonair","cta":"Open the word card","title":"In a sentence · debonair","body":"a debonair gentleman","clip":1},"wh-debonair":{"src":"concept:22:words:9:hook","route":"#/word/debonair","cta":"Open the word card","title":"Remember it · debonair","body":"A debonair gentleman has good AIR about him — the word ends in 'air' because his charm is breezy."},"wo-debonair":{"src":"lore:debonair:0","route":"#/word/debonair","cta":"Open the word card","title":"Where it comes from · debonair","body":"French de bon aire = of good disposition/origin"},"wd-deprecate":{"src":"concept:22:words:10:def","route":"#/word/deprecate","cta":"Open the word card","title":"deprecate","roman":"DEH-pruh-kayt","body":"express strong disapproval of; deplore","clip":1},"wx-deprecate":{"src":"concept:22:words:10:ex","route":"#/word/deprecate","cta":"Open the word card","title":"In a sentence · deprecate","body":"The teacher should not deprecate his student's efforts","clip":1},"wh-deprecate":{"src":"concept:22:words:10:hook","route":"#/word/deprecate","cta":"Open the word card","title":"Remember it · deprecate","body":"To DEPREcate is to PRAY something away — de+PREC(prayer)+ate, like a priest praying against evil."},"wo-deprecate":{"src":"lore:deprecate:0","route":"#/word/deprecate","cta":"Open the word card","title":"Where it comes from · deprecate","body":"Latin deprecari = to pray against, avert by prayer"},"wd-depreciate":{"src":"concept:22:words:11:def","route":"#/word/depreciate","cta":"Open the word card","title":"depreciate","roman":"dih-PREE-shee-ayt","body":"To reduce or lessen the value, worth, or importance of something; to belittle something or cause it to decrease in monetary or perceived value over time.","clip":1},"wx-depreciate":{"src":"concept:22:words:11:ex","route":"#/word/depreciate","cta":"Open the word card","title":"In a sentence · depreciate","body":"Cars depreciate quickly, so Dad's five-year-old van is worth half what he paid.","clip":1},"wh-depreciate":{"src":"concept:22:words:11:hook","route":"#/word/depreciate","cta":"Open the word card","title":"Remember it · depreciate","body":"To depreciate is to lower the PRICE — keep 'preci' in the middle to remember the price root."},"wo-depreciate":{"src":"lore:depreciate:0","route":"#/word/depreciate","cta":"Open the word card","title":"Where it comes from · depreciate","body":"Latin depretiare = to lower the price; pretium = price"},"wd-deference":{"src":"concept:22:words:12:def","route":"#/word/deference","cta":"Open the word card","title":"deference","roman":"DEH-fer-uhns","body":"a courteous expression (by word or deed) of esteem or regard","clip":1},"wx-deference":{"src":"concept:22:words:12:ex","route":"#/word/deference","cta":"Open the word card","title":"In a sentence · deference","body":"his deference to her wishes was very flattering","clip":1},"wh-deference":{"src":"concept:22:words:12:hook","route":"#/word/deference","cta":"Open the word card","title":"Remember it · deference","body":"Show DEFERENCe by letting others go FIRST — spot DEFER inside deFERENCE and add -ENCE."},"wo-deference":{"src":"lore:deference:0","route":"#/word/deference","cta":"Open the word card","title":"Where it comes from · deference","body":"Latin deferre = to carry, yield"},"wd-deign":{"src":"concept:22:words:13:def","route":"#/word/deign","cta":"Open the word card","title":"deign","roman":"d-AY-n","body":"to think fit or to condescend","clip":1},"wx-deign":{"src":"concept:22:words:13:ex","route":"#/word/deign","cta":"Open the word card","title":"In a sentence · deign","body":"The famous chef did not deign to answer questions from food bloggers he considered beneath his level of expertise.","clip":1},"wh-deign":{"src":"concept:22:words:13:hook","route":"#/word/deign","cta":"Open the word card","title":"Remember it · deign","body":"The queen would not DEIGN to explain — she has DIGNITY and DEIGN share the same root; both have the silent GN."},"wo-deign":{"src":"lore:deign:0","route":"#/word/deign","cta":"Open the word card","title":"Where it comes from · deign","body":"Latin dignari = to consider worthy, from dignus = worthy"},"wd-detriment":{"src":"concept:22:words:14:def","route":"#/word/detriment","cta":"Open the word card","title":"detriment","roman":"DEH-truh-muhnt","body":"a damage or loss","clip":1},"wx-detriment":{"src":"concept:22:words:14:ex","route":"#/word/detriment","cta":"Open the word card","title":"In a sentence · detriment","body":"Staying up until midnight every night was a clear detriment to his ability to focus in class.","clip":1},"wh-detriment":{"src":"concept:22:words:14:hook","route":"#/word/detriment","cta":"Open the word card","title":"Remember it · detriment","body":"DETRIMENT ends in -MENT likeMENT-al damage — remember DE-TRI-MENT: rubbing away leaves a MENT-al scar."},"wo-detriment":{"src":"lore:detriment:0","route":"#/word/detriment","cta":"Open the word card","title":"Where it comes from · detriment","body":"Latin detrimentum = rubbing away, damage"},"wd-derogate":{"src":"concept:22:words:15:def","route":"#/word/derogate","cta":"Open the word card","title":"derogate","roman":"DER-uh-gate","body":"cause to seem less serious; play down","clip":1},"wx-derogate":{"src":"concept:22:words:15:ex","route":"#/word/derogate","cta":"Open the word card","title":"In a sentence · derogate","body":"She tried to derogate his achievements, but everyone in the room knew how hard he had worked.","clip":1},"wh-derogate":{"src":"concept:22:words:15:hook","route":"#/word/derogate","cta":"Open the word card","title":"Remember it · derogate","body":"DEROGATE: to take away (de) from someone's ROGUE-ness — ask (rogare) less of them, spelled de+ROG+ATE."},"wo-derogate":{"src":"lore:derogate:0","route":"#/word/derogate","cta":"Open the word card","title":"Where it comes from · derogate","body":"Latin derogare = to detract from, repeal in part"},"li-u28":{"src":"concept:23:concept","route":"#/stop/u28","cta":"Open this stop","title":"ex- / e- / ef- (out / former / thoroughly)","body":"Latin ex- = out of. It appears as ex-, e-, or ef- depending on what follows. Before f it assimilates to ef-; before many consonants the x drops to just e-. Same prefix, three shapes."},"lc-u28-0":{"src":"concept:23:cards:0","route":"#/stop/u28","cta":"Open this stop","title":"ex- / e- / ef- (out / former / thoroughly) · Three Forms","body":"ex- before vowels and most consonants: exquisite, extraneous. Before f → ef-: effervescent (ef- + fervere = boil = bubbling over), efface (ef- + facies = face = rub out). Before many consonants the x drops to e-: eloquent, elaborate, elicit, emit."},"lc-u28-1":{"src":"concept:23:cards:1","route":"#/stop/u28","cta":"Open this stop","title":"ex- / e- / ef- (out / former / thoroughly) · Out-Of Words","body":"Excoriate (ex- + corium = skin) = strip the skin = criticize savagely. Exculpate (ex- + culpa = fault) = free from blame. Exigent (ex- + agere = drive out) = pressing, urgent. Exiguous = extremely scanty. Expatiate = speak at great length. Expunge (ex- + pungere = prick) = erase entirely."},"lc-u28-2":{"src":"concept:23:cards:2","route":"#/stop/u28","cta":"Open this stop","title":"ex- / e- / ef- (out / former / thoroughly) · Former / From Words","body":"Ex- before a title = former: ex-president. Expatriate = one who has left their homeland. Extirpate = pull out by the roots. Exhume (ex- + humus = earth) = dig out of the ground."},"lc-u28-3":{"src":"concept:23:cards:3","route":"#/stop/u28","cta":"Open this stop","title":"ex- / e- / ef- (out / former / thoroughly) · Thorough / Intensive ex-","body":"ex- intensifies the root: exacerbate = make thoroughly more bitter/worse. Exasperate = thoroughly roughen = irritate deeply. Excruciating (ex- + crux = cross) = thoroughly cross-like = intensely painful. Exhilarating = thoroughly lift the spirits."},"lc-u28-4":{"src":"concept:23:cards:4","route":"#/stop/u28","cta":"Open this stop","title":"ex- / e- / ef- (out / former / thoroughly) · Spelling Traps","body":"Exquisite = E-X-Q-U-I-S-I-T-E (not exquissite). Extemporaneous = E-X-T-E-M-P-O-R-A-N-E-O-U-S — from ex tempore = out of the moment. Extraordinary = E-X-T-R-A-O-R-D-I-N-A-R-Y — note: extra- here not ex-! Different prefix entirely."},"uq-u28-3":{"src":"unit:u28:qs:3","route":"#/stop/u28","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ things are EXceptionallyQUISITELY crafted” — which word is this hook about?","opts":["exquisite","extemporaneous","effervescent","exacerbate"],"after":"From “ex- / e- / ef- (out / former / thoroughly)”."}},"wd-exquisite":{"src":"concept:23:words:0:def","route":"#/word/exquisite","cta":"Open the word card","title":"exquisite","roman":"EH-k-s-k-w-uh-z-uh-t","body":"of special beauty or charm","clip":1},"wx-exquisite":{"src":"concept:23:words:0:ex","route":"#/word/exquisite","cta":"Open the word card","title":"In a sentence · exquisite","body":"suffered exquisite pain","clip":1},"wh-exquisite":{"src":"concept:23:words:0:hook","route":"#/word/exquisite","cta":"Open the word card","title":"Remember it · exquisite","body":"EXQUISITE things are EXceptionallyQUISITELY crafted"},"wo-exquisite":{"src":"lore:exquisite:0","route":"#/word/exquisite","cta":"Open the word card","title":"Where it comes from · exquisite","body":"Latin exquisitus = carefully sought out, from exquirere = to search out"},"wd-extemporaneous":{"src":"concept:23:words:1:def","route":"#/word/extemporaneous","cta":"Open the word card","title":"extemporaneous","roman":"ek-stem-puh-RAY-nee-us","body":"done without special preparation","clip":1},"wx-extemporaneous":{"src":"concept:23:words:1:ex","route":"#/word/extemporaneous","cta":"Open the word card","title":"In a sentence · extemporaneous","body":"Asked to speak with no warning, Jonah gave an extemporaneous talk about his turtle.","clip":1},"wh-extemporaneous":{"src":"concept:23:words:1:hook","route":"#/word/extemporaneous","cta":"Open the word card","title":"Remember it · extemporaneous","body":"EX TEMPORE means 'out of the moment'—no prep time!"},"wo-extemporaneous":{"src":"lore:extemporaneous:0","route":"#/word/extemporaneous","cta":"Open the word card","title":"Where it comes from · extemporaneous","body":"Latin ex tempore = out of the time (on the spot)"},"wd-exacerbate":{"src":"concept:23:words:3:def","route":"#/word/exacerbate","cta":"Open the word card","title":"exacerbate","roman":"ih-g-z-A-s-ur-b-ay-t","body":"to make something worse","clip":1},"wx-exacerbate":{"src":"concept:23:words:3:ex","route":"#/word/exacerbate","cta":"Open the word card","title":"In a sentence · exacerbate","body":"Scratching the mosquito bite will only exacerbate the itching and make it redder.","clip":1},"wh-exacerbate":{"src":"concept:23:words:3:hook","route":"#/word/exacerbate","cta":"Open the word card","title":"Remember it · exacerbate","body":"To exACERBate is to make things ACERBic — bitterly worse."},"wo-exacerbate":{"src":"lore:exacerbate:0","route":"#/word/exacerbate","cta":"Open the word card","title":"Where it comes from · exacerbate","body":"Latin acerbus = harsh, bitter"},"wd-exasperate":{"src":"concept:23:words:4:def","route":"#/word/exasperate","cta":"Open the word card","title":"exasperate","roman":"ih-GZA-sper-ayt","body":"to irritate intensely; to make someone very annoyed or frustrated","clip":1},"wx-exasperate":{"src":"concept:23:words:4:ex","route":"#/word/exasperate","cta":"Open the word card","title":"In a sentence · exasperate","body":"It began to exasperate her teammates when she changed the project plan for the fifth time the night before it was due.","clip":1},"wh-exasperate":{"src":"concept:23:words:4:hook","route":"#/word/exasperate","cta":"Open the word card","title":"Remember it · exasperate","body":"exASPERate — it makes things ASPERously rough and irritating"},"wo-exasperate":{"src":"lore:exasperate:0","route":"#/word/exasperate","cta":"Open the word card","title":"Where it comes from · exasperate","body":"Latin exasperare = to make rough, from ex- (intensive) + asper = rough"},"wd-excruciating":{"src":"concept:23:words:5:def","route":"#/word/excruciating","cta":"Open the word card","title":"excruciating","roman":"ih-KSKROO-shee-ay-tihng","body":"causing very intense pain or distress","clip":1},"wx-excruciating":{"src":"concept:23:words:5:ex","route":"#/word/excruciating","cta":"Open the word card","title":"In a sentence · excruciating","body":"Waiting for the results was excruciating, and Tara checked the website every single minute.","clip":1},"wh-excruciating":{"src":"concept:23:words:5:hook","route":"#/word/excruciating","cta":"Open the word card","title":"Remember it · excruciating","body":"exCRUCIating pain — see the CRUCI as in crucifix — nailed to the cross level of pain!"},"wo-excruciating":{"src":"lore:excruciating:0","route":"#/word/excruciating","cta":"Open the word card","title":"Where it comes from · excruciating","body":"Latin excruciare = to torture, from crux = cross"},"wd-exhilarate":{"src":"concept:23:words:6:def","route":"#/word/exhilarate","cta":"Open the word card","title":"exhilarate","roman":"ih-GZIH-ler-ayt","body":"fill with sublime emotion","clip":1},"wx-exhilarate":{"src":"concept:23:words:6:ex","route":"#/word/exhilarate","cta":"Open the word card","title":"In a sentence · exhilarate","body":"Racing downhill on our bikes exhilarated us until we were breathless and grinning.","clip":1},"wh-exhilarate":{"src":"concept:23:words:6:hook","route":"#/word/exhilarate","cta":"Open the word card","title":"Remember it · exhilarate","body":"EXHILARATE has a hidden 'h' and only one 'l' — feel the HILARIOUS joy in 'hilar'!"},"wo-exhilarate":{"src":"lore:exhilarate:0","route":"#/word/exhilarate","cta":"Open the word card","title":"Where it comes from · exhilarate","body":"Latin exhilarare = to gladden (ex = thoroughly + hilaris = cheerful)"},"wd-excoriate":{"src":"concept:23:words:7:def","route":"#/word/excoriate","cta":"Open the word card","title":"excoriate","roman":"eh-KSKAW-ree-ayt","body":"express strong disapproval of","clip":1},"wx-excoriate":{"src":"concept:23:words:7:ex","route":"#/word/excoriate","cta":"Open the word card","title":"In a sentence · excoriate","body":"Coach excoriated the team for leaving litter all over the changing room floor.","clip":1},"wh-excoriate":{"src":"concept:23:words:7:hook","route":"#/word/excoriate","cta":"Open the word card","title":"Remember it · excoriate","body":"exCORIATE — the CORE of your skin is stripped away, leaving an I and ATE ending!"},"wo-excoriate":{"src":"lore:excoriate:0","route":"#/word/excoriate","cta":"Open the word card","title":"Where it comes from · excoriate","body":"Latin excoriare = to strip the hide, from corium = skin"},"wd-exculpate":{"src":"concept:23:words:8:def","route":"#/word/exculpate","cta":"Open the word card","title":"exculpate","roman":"eh-KSKUH-lpayt","body":"to clear someone of blame or of an accusation of wrongdoing","clip":1},"wx-exculpate":{"src":"concept:23:words:8:ex","route":"#/word/exculpate","cta":"Open the word card","title":"In a sentence · exculpate","body":"Security footage exculpated Dev, proving he was in the library when the window cracked.","clip":1},"wh-exculpate":{"src":"concept:23:words:8:hook","route":"#/word/exculpate","cta":"Open the word card","title":"Remember it · exculpate","body":"EX means OUT — exculpate pulls the CULPRIT out of blame."},"wo-exculpate":{"src":"lore:exculpate:0","route":"#/word/exculpate","cta":"Open the word card","title":"Where it comes from · exculpate","body":"Latin ex (out) + culpa (fault/blame)"},"wd-exigent":{"src":"concept:23:words:9:def","route":"#/word/exigent","cta":"Open the word card","title":"exigent","roman":"EH-ksih-juhnt","body":"demanding attention; ;","clip":1},"wx-exigent":{"src":"concept:23:words:9:ex","route":"#/word/exigent","cta":"Open the word card","title":"In a sentence · exigent","body":"The emergency room doctor faced an exigent situation when three critically injured patients arrived at exactly the same moment, requiring her to make rapid decisions that could mean the difference between life and death.","clip":1},"wh-exigent":{"src":"concept:23:words:9:hook","route":"#/word/exigent","cta":"Open the word card","title":"Remember it · exigent","body":"An EXIgent situation is URGENT — both end in -ent, demanding your immediate attention."},"wd-expatiate":{"src":"concept:23:words:10:def","route":"#/word/expatiate","cta":"Open the word card","title":"expatiate","roman":"ik-SPAY-shee-ayt","body":"to speak or write at length; to add details and elaborate on a subject freely","clip":1},"wx-expatiate":{"src":"concept:23:words:10:ex","route":"#/word/expatiate","cta":"Open the word card","title":"In a sentence · expatiate","body":"The professor asked the students not to expatiate on every minor point but to focus on the main argument.","clip":1},"wh-expatiate":{"src":"concept:23:words:10:hook","route":"#/word/expatiate","cta":"Open the word card","title":"Remember it · expatiate","body":"To expatiate is to spread your ideas across SPACIOUS territory"},"wo-expatiate":{"src":"lore:expatiate:0","route":"#/word/expatiate","cta":"Open the word card","title":"Where it comes from · expatiate","body":"Latin spatiari = to walk about, from spatium = space"},"wd-expunge":{"src":"concept:23:words:11:def","route":"#/word/expunge","cta":"Open the word card","title":"expunge","roman":"ih-KSPUHNJ","body":"remove by erasing or crossing out or as if by drawing a line","clip":1},"wx-expunge":{"src":"concept:23:words:11:ex","route":"#/word/expunge","cta":"Open the word card","title":"In a sentence · expunge","body":"Librarians expunged my overdue fine from the record after I returned the lost book.","clip":1},"wh-expunge":{"src":"concept:23:words:11:hook","route":"#/word/expunge","cta":"Open the word card","title":"Remember it · expunge","body":"Expunge has a PLUNGE-like ending — plunge your eraser in and wipe it out, keeping the E at the end."},"wd-extirpate":{"src":"concept:23:words:12:def","route":"#/word/extirpate","cta":"Open the word card","title":"extirpate","roman":"EH-kster-payt","body":"destroy completely, as if down to the roots","clip":1},"wx-extirpate":{"src":"concept:23:words:12:ex","route":"#/word/extirpate","cta":"Open the word card","title":"In a sentence · extirpate","body":"Gardeners worked all spring to extirpate the weeds, digging out every last root.","clip":1},"wh-extirpate":{"src":"concept:23:words:12:hook","route":"#/word/extirpate","cta":"Open the word card","title":"Remember it · extirpate","body":"EX-STIR-PATE: to extirpate is to stir up and pull out by the root — stir is hidden right inside."},"wo-extirpate":{"src":"lore:extirpate:0","route":"#/word/extirpate","cta":"Open the word card","title":"Where it comes from · extirpate","body":"Latin exstirpare = to root out (stirps = root, stem)"},"wd-elaborate":{"src":"concept:23:words:14:def","route":"#/word/elaborate","cta":"Open the word card","title":"elaborate","roman":"ih-LA-bruht","body":"add details, as to an account or idea; clarify the meaning of and discourse in a learned way, usually in writing","clip":1},"wx-elaborate":{"src":"concept:23:words:14:ex","route":"#/word/elaborate","cta":"Open the word card","title":"In a sentence · elaborate","body":"She elaborated on the main ideas in her dissertation","clip":1},"wh-elaborate":{"src":"concept:23:words:14:hook","route":"#/word/elaborate","cta":"Open the word card","title":"Remember it · elaborate","body":"ELABORATE means to work OUT the details — e+LABOR+ate; there's real LABOR in the middle of this word."},"wo-elaborate":{"src":"lore:elaborate:0","route":"#/word/elaborate","cta":"Open the word card","title":"Where it comes from · elaborate","body":"Latin e = out + laborare = to work"},"li-u29":{"src":"concept:24:concept","route":"#/stop/u29","cta":"Open this stop","title":"re- (again / back)","body":"Latin re- = again or back. One of the most common prefixes in English. But beware: not every word starting with re- uses it as a prefix — sometimes it is part of the root itself."},"lc-u29-0":{"src":"concept:24:cards:0","route":"#/stop/u29","cta":"Open this stop","title":"re- (again / back) · What re- Does","body":"re- = again (redo, restart) or back (return, retract). Recalcitrant (re- + calcitrare = kick) = kicking back = stubbornly resistant. Redoubtable (re- + douter = fear) = worth fearing again and again. Repartee = a quick, ready reply. Recidivism (re- + cadere = fall) = falling back into crime."},"lc-u29-1":{"src":"concept:24:cards:1","route":"#/stop/u29","cta":"Open this stop","title":"re- (again / back) · Again Words","body":"Renaissance (re- + naissance = birth) = rebirth. Rendezvous = meet again at a set place. Reconnoiter (re- + connoître = know) = look over again to gather information. Rescind (re- + scindere = cut) = cut back = cancel. Remonstrate (re- + monstrare = show) = show opposition again = protest."},"lc-u29-2":{"src":"concept:24:cards:2","route":"#/stop/u29","cta":"Open this stop","title":"re- (again / back) · Back Words","body":"Repudiate (re- + pudere = shame) = push back with rejection. Recriminate = re- + criminare = counter-accuse. Retract (re- + trahere = drag) = drag back = withdraw a statement. Recant = withdraw a previously stated belief. Renounce = formally give up a claim."},"lc-u29-3":{"src":"concept:24:cards:3","route":"#/stop/u29","cta":"Open this stop","title":"re- (again / back) · When re- is NOT a Prefix","body":"Reticent = reticere (be silent) — the re- is part of the Latin root. Relevant — re- is part of relevare. Test: remove re- — if the remainder is not a meaningful English word, re- is part of the root. Reticent minus re- = ticent (not a word) → part of root."},"lc-u29-4":{"src":"concept:24:cards:4","route":"#/stop/u29","cta":"Open this stop","title":"re- (again / back) · French re- Spelling Traps","body":"Rendezvous = R-E-N-D-E-Z-V-O-U-S (French; final -s silent). Renaissance = R-E-N-A-I-S-S-A-N-C-E (double-s). Reconnaissance = R-E-C-O-N-N-A-I-S-S-A-N-C-E (double-n AND double-s). These French re- words carry French spelling patterns inside them."},"uq-u29-3":{"src":"unit:u29:qs:3","route":"#/stop/u29","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A ▁▁▁ student kicks back like a mule — remember the ANT who refuses to march.” — which word is this hook about?","opts":["recalcitrant","redoubtable","repartee","renaissance"],"after":"From “re- (again / back)”."}},"wd-recalcitrant":{"src":"concept:24:words:0:def","route":"#/word/recalcitrant","cta":"Open the word card","title":"recalcitrant","roman":"r-ih-k-A-l-s-ih-t-r-uh-n-t","body":"means resisting authority","clip":1},"wx-recalcitrant":{"src":"concept:24:words:0:ex","route":"#/word/recalcitrant","cta":"Open the word card","title":"In a sentence · recalcitrant","body":"Our recalcitrant pony refused every command and would not budge from the gate.","clip":1},"wh-recalcitrant":{"src":"concept:24:words:0:hook","route":"#/word/recalcitrant","cta":"Open the word card","title":"Remember it · recalcitrant","body":"A rECALCITRANT student kicks back like a mule — remember the ANT who refuses to march."},"wo-recalcitrant":{"src":"lore:recalcitrant:0","route":"#/word/recalcitrant","cta":"Open the word card","title":"Where it comes from · recalcitrant","body":"Latin recalcitrare = to kick back (calx = heel)"},"wd-redoubtable":{"src":"concept:24:words:1:def","route":"#/word/redoubtable","cta":"Open the word card","title":"redoubtable","roman":"r-uh-d-OW-t-uh-b-uh-l","body":"that that is to be feared formidable","clip":1},"wx-redoubtable":{"src":"concept:24:words:1:ex","route":"#/word/redoubtable","cta":"Open the word card","title":"In a sentence · redoubtable","body":"Facing the county's redoubtable chess champion, our small club still hoped for one draw.","clip":1},"wh-redoubtable":{"src":"concept:24:words:1:hook","route":"#/word/redoubtable","cta":"Open the word card","title":"Remember it · redoubtable","body":"A redouBTable foe makes you doubt — the B hides silently in the middle like a lurking enemy."},"wo-redoubtable":{"src":"lore:redoubtable:0","route":"#/word/redoubtable","cta":"Open the word card","title":"Where it comes from · redoubtable","body":"French redoutable = fearsome, from redouter = to dread"},"wd-repartee":{"src":"concept:24:words:2:def","route":"#/word/repartee","cta":"Open the word card","title":"repartee","roman":"r-eh-p-ur-t-EE","body":"a quick witty reply","clip":1},"wx-repartee":{"src":"concept:24:words:2:ex","route":"#/word/repartee","cta":"Open the word card","title":"In a sentence · repartee","body":"The debate champion's sharp repartee left her opponent speechless and the audience laughing.","clip":1},"wh-repartee":{"src":"concept:24:words:2:hook","route":"#/word/repartee","cta":"Open the word card","title":"Remember it · repartee","body":"Good repartee ends with a TEE shot — it always lands perfectly"},"wo-repartee":{"src":"lore:repartee:0","route":"#/word/repartee","cta":"Open the word card","title":"Where it comes from · repartee","body":"French repartir = to set out again, reply quickly"},"wd-renaissance":{"src":"concept:24:words:3:def","route":"#/word/renaissance","cta":"Open the word card","title":"renaissance","roman":"reh-nuh-SAHNS","body":"the period of European history at the close of the Middle Ages and the rise of the modern world; a cultural rebirth from the 14th through the middle of the 17th centuries","clip":1},"wx-renaissance":{"src":"concept:24:words:3:ex","route":"#/word/renaissance","cta":"Open the word card","title":"In a sentence · renaissance","body":"Artists from across Europe were inspired by the renaissance, filling cathedrals and palaces with breathtaking paintings and sculptures.","clip":1},"wh-renaissance":{"src":"concept:24:words:3:hook","route":"#/word/renaissance","cta":"Open the word card","title":"Remember it · renaissance","body":"RENAISSANCE = RE + NAIS + SANCE — one 'n,' one 's': a rebirth needs only one of each to spring anew."},"wo-renaissance":{"src":"lore:renaissance:0","route":"#/word/renaissance","cta":"Open the word card","title":"Where it comes from · renaissance","body":"French re- = again + naissance = birth (Latin nasci)"},"wd-rendezvous":{"src":"concept:24:words:4:def","route":"#/word/rendezvous","cta":"Open the word card","title":"rendezvous","roman":"RAH-ndih-voo","body":"a meeting planned at a certain time and place","clip":1},"wx-rendezvous":{"src":"concept:24:words:4:ex","route":"#/word/rendezvous","cta":"Open the word card","title":"In a sentence · rendezvous","body":"he was waiting for them at the rendezvous","clip":1},"wh-rendezvous":{"src":"concept:24:words:4:hook","route":"#/word/rendezvous","cta":"Open the word card","title":"Remember it · rendezvous","body":"RENDEZVOUS ends in -vous — you (vous) must show up at the meeting!"},"wo-rendezvous":{"src":"lore:rendezvous:0","route":"#/word/rendezvous","cta":"Open the word card","title":"Where it comes from · rendezvous","body":"French rendez-vous = present yourselves"},"wd-reconnoiter":{"src":"concept:24:words:5:def","route":"#/word/reconnoiter","cta":"Open the word card","title":"reconnoiter","roman":"ree-kuh-NOY-ter","body":"explore, often with the goal of finding something or somebody","clip":1},"wx-reconnoiter":{"src":"concept:24:words:5:ex","route":"#/word/reconnoiter","cta":"Open the word card","title":"In a sentence · reconnoiter","body":"The scouts were sent ahead to reconnoiter the forest trail before the rest of the troop attempted the hike.","clip":1},"wh-reconnoiter":{"src":"concept:24:words:5:hook","route":"#/word/reconnoiter","cta":"Open the word card","title":"Remember it · reconnoiter","body":"RE + CONnoiter — go out again to CONfirm what's out there"},"wo-reconnoiter":{"src":"lore:reconnoiter:0","route":"#/word/reconnoiter","cta":"Open the word card","title":"Where it comes from · reconnoiter","body":"French reconnaître = to recognize, from Latin recognoscere = to know again"},"wd-recidivism":{"src":"concept:24:words:6:def","route":"#/word/recidivism","cta":"Open the word card","title":"recidivism","roman":"ruh-SIH-dih-vih-zuhm","body":"habitual relapse into crime","clip":1},"wx-recidivism":{"src":"concept:24:words:6:ex","route":"#/word/recidivism","cta":"Open the word card","title":"In a sentence · recidivism","body":"The new rehabilitation program was designed specifically to reduce recidivism among young offenders.","clip":1},"wh-recidivism":{"src":"concept:24:words:6:hook","route":"#/word/recidivism","cta":"Open the word card","title":"Remember it · recidivism","body":"ReCIDivism: criminals who keep falling back — the CID (like 'slide') takes them down again and again."},"wo-recidivism":{"src":"lore:recidivism:0","route":"#/word/recidivism","cta":"Open the word card","title":"Where it comes from · recidivism","body":"Latin recidivus = falling back, from recidere = to fall back"},"wd-repudiate":{"src":"concept:24:words:7:def","route":"#/word/repudiate","cta":"Open the word card","title":"repudiate","roman":"ree-PYOO-dee-ayt","body":"To firmly reject, deny, or refuse to accept something such as a claim, belief, or person, often publicly cutting all ties with it.","clip":1},"wx-repudiate":{"src":"concept:24:words:7:ex","route":"#/word/repudiate","cta":"Open the word card","title":"In a sentence · repudiate","body":"The scientist was quick to repudiate the false data that had been attributed to her research lab.","clip":1},"wh-repudiate":{"src":"concept:24:words:7:hook","route":"#/word/repudiate","cta":"Open the word card","title":"Remember it · repudiate","body":"To REPUDIATE is to say PUT it away — I want nothing to do with it"},"wo-repudiate":{"src":"lore:repudiate:0","route":"#/word/repudiate","cta":"Open the word card","title":"Where it comes from · repudiate","body":"Latin repudiare = to divorce, reject"},"wd-rescind":{"src":"concept:24:words:8:def","route":"#/word/rescind","cta":"Open the word card","title":"rescind","roman":"r-ih-s-IH-n-d","body":"to annul or repeal","clip":1},"wx-rescind":{"src":"concept:24:words:8:ex","route":"#/word/rescind","cta":"Open the word card","title":"In a sentence · rescind","body":"The head teacher rescinded the ban on ball games after we promised to be careful.","clip":1},"wh-rescind":{"src":"concept:24:words:8:hook","route":"#/word/rescind","cta":"Open the word card","title":"Remember it · rescind","body":"ResCIND has a hidden SC — to reSCind is to CUT back a law, and SC cuts right through the middle."},"wo-rescind":{"src":"lore:rescind:0","route":"#/word/rescind","cta":"Open the word card","title":"Where it comes from · rescind","body":"Latin rescindere = re-(back)+scindere(to cut)"},"wd-recriminate":{"src":"concept:24:words:10:def","route":"#/word/recriminate","cta":"Open the word card","title":"recriminate","roman":"rih-krih-mih-NAYT","body":"return an accusation against someone or engage in mutual accusations; charge in return","clip":1},"wx-recriminate":{"src":"concept:24:words:10:ex","route":"#/word/recriminate","cta":"Open the word card","title":"In a sentence · recriminate","body":"Instead of working together to solve the problem, the two teammates began to recriminate each other publicly.","clip":1},"wh-recriminate":{"src":"concept:24:words:10:hook","route":"#/word/recriminate","cta":"Open the word card","title":"Remember it · recriminate","body":"To RECRIMINATE is to CRIME-back — you throw the CRIMIN-ation right back."},"wo-recriminate":{"src":"lore:recriminate:0","route":"#/word/recriminate","cta":"Open the word card","title":"Where it comes from · recriminate","body":"Latin recriminari = to accuse in return"},"wd-retract":{"src":"concept:24:words:11:def","route":"#/word/retract","cta":"Open the word card","title":"retract","roman":"ree-TRAKT","body":"formally reject or disavow a formerly held belief, usually under pressure","clip":1},"wx-retract":{"src":"concept:24:words:11:ex","route":"#/word/retract","cta":"Open the word card","title":"In a sentence · retract","body":"He retracted his earlier statements about his religion","clip":1},"wh-retract":{"src":"concept:24:words:11:hook","route":"#/word/retract","cta":"Open the word card","title":"Remember it · retract","body":"RETRACT pulls back — like a TRACTor in reverse: re-TRACT."},"wx-recant":{"src":"concept:24:words:12:ex","route":"#/word/recant","cta":"Open the word card","title":"In a sentence · recant","body":"Pressed by the council, the scholar refused to recant his belief that Earth moves.","clip":1},"wh-recant":{"src":"concept:24:words:12:hook","route":"#/word/recant","cta":"Open the word card","title":"Remember it · recant","body":"rECANT: to take back what you CHANTED before — unsing your song of belief."},"wd-renounce":{"src":"concept:24:words:13:def","route":"#/word/renounce","cta":"Open the word card","title":"renounce","roman":"rih-NOWNS","body":"give up, such as power, as of monarchs and emperors, or duties and obligations","clip":1},"wx-renounce":{"src":"concept:24:words:13:ex","route":"#/word/renounce","cta":"Open the word card","title":"In a sentence · renounce","body":"Weary of ruling, the old queen renounced her throne and retired to a cottage.","clip":1},"wh-renounce":{"src":"concept:24:words:13:hook","route":"#/word/renounce","cta":"Open the word card","title":"Remember it · renounce","body":"To reNOUNCE is to take back your NOUN — your name or claim — so find NOUNCE inside."},"wo-renounce":{"src":"lore:renounce:0","route":"#/word/renounce","cta":"Open the word card","title":"Where it comes from · renounce","body":"Latin renuntiare = to protest, renounce"},"wd-recondite":{"src":"concept:24:words:14:def","route":"#/word/recondite","cta":"Open the word card","title":"recondite","roman":"REH-kuh-ndeyet","body":"difficult to penetrate; incomprehensible to one of ordinary understanding or knowledge","clip":1},"wx-recondite":{"src":"concept:24:words:14:ex","route":"#/word/recondite","cta":"Open the word card","title":"In a sentence · recondite","body":"Grandpa's recondite book about ancient coins baffled everyone except the museum expert.","clip":1},"wh-recondite":{"src":"concept:24:words:14:hook","route":"#/word/recondite","cta":"Open the word card","title":"Remember it · recondite","body":"RECONDite knowledge is hidden — it's conDITed (stored) away where few can DITE it out."},"wo-recondite":{"src":"lore:recondite:0","route":"#/word/recondite","cta":"Open the word card","title":"Where it comes from · recondite","body":"Latin reconditus = hidden, stored away"},"wd-refulgent":{"src":"concept:24:words:15:def","route":"#/word/refulgent","cta":"Open the word card","title":"refulgent","roman":"rih-FUL-jent","body":"radiating or as if radiating light","clip":1},"wx-refulgent":{"src":"concept:24:words:15:ex","route":"#/word/refulgent","cta":"Open the word card","title":"In a sentence · refulgent","body":"The refulgent glow of the full moon was so brilliantly bright on the snowy mountaintop that the hikers could clearly read their trail map without needing a flashlight at all.","clip":1},"wh-refulgent":{"src":"concept:24:words:15:hook","route":"#/word/refulgent","cta":"Open the word card","title":"Remember it · refulgent","body":"reFULGent — FULG sounds like FULL of light; it ends in -ENT not -ANT."},"wo-refulgent":{"src":"lore:refulgent:0","route":"#/word/refulgent","cta":"Open the word card","title":"Where it comes from · refulgent","body":"Latin refulgere = to flash back (re- + fulgere = to shine)"},"li-u30":{"src":"concept:25:concept","route":"#/stop/u30","cta":"Open this stop","title":"pre- / pro- (before / forward)","body":"Latin pre- = before in time or position. Latin pro- = forward, in favor of, on behalf of. Two prefixes, closely related in meaning, producing very different vocabularies."},"lc-u30-0":{"src":"concept:25:cards:0","route":"#/stop/u30","cta":"Open this stop","title":"pre- / pro- (before / forward) · pre- = Before","body":"Precocious (pre- + coquere = cook) = cooked before its time = unusually mature early. Precursor = one who runs before. Prescient (pre- + scire = know) = knowing before it happens. Preponderant (pre- + ponderare = weigh) = weighing more = dominant. Prevaricate = straddle before = dodge the truth."},"lc-u30-1":{"src":"concept:25:cards:1","route":"#/stop/u30","cta":"Open this stop","title":"pre- / pro- (before / forward) · pro- = Forward / For","body":"Propitious (pro- + pietas = favor) = presenting favorable signs ahead. Prodigious = extraordinarily great. Provenance (pro- + venire = come) = where something came from. Protagonist (pro- + Greek agonist = actor) = the forward-acting main character. Profligate = wildly extravagant."},"lc-u30-2":{"src":"concept:25:cards:2","route":"#/stop/u30","cta":"Open this stop","title":"pre- / pro- (before / forward) · The Key pre- Spelling Detail","body":"Precocious = P-R-E-C-O-C-I-O-U-S (two c's; the first comes from prefix + root). Prescience = P-R-E-S-C-I-E-N-C-E (the sc- cluster from scire). Predilection = P-R-E-D-I-L-E-C-T-I-O-N — note -lection not -lekshun."},"lc-u30-3":{"src":"concept:25:cards:3","route":"#/stop/u30","cta":"Open this stop","title":"pre- / pro- (before / forward) · Prescribe vs Proscribe","body":"Prescribe (pre- + scribere = write before) = a doctor writes a prescription in advance. Proscribe (pro- = put forward publicly) = ban or forbid. A doctor prescribes; a government proscribes. Precede (come before) vs proceed (move forward). Same-sounding prefixes, opposite directions."},"lc-u30-4":{"src":"concept:25:cards:4","route":"#/stop/u30","cta":"Open this stop","title":"pre- / pro- (before / forward) · Prodigal & Prodigious","body":"Prodigal (prodigere = drive forward wastefully) = wastefully extravagant. Prodigious (prodire = go forward beyond normal) = extraordinarily great in size or degree. Both from pro- but from different Latin roots — the definitions distinguish them clearly at the bee."},"uq-u30-3":{"src":"unit:u30:qs:3","route":"#/stop/u30","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A ▁▁▁ child is PRECIOUS but EARLY — ▁▁▁, that -ious ending means full of early ripeness.” — which word is this hook about?","opts":["precocious","precursor","prescient","preponderant"],"after":"From “pre- / pro- (before / forward)”."}},"wd-precocious":{"src":"concept:25:words:0:def","route":"#/word/precocious","cta":"Open the word card","title":"precocious","roman":"p-r-ih-k-OH-sh-uh-s","body":"prematurely developed","clip":1},"wx-precocious":{"src":"concept:25:words:0:ex","route":"#/word/precocious","cta":"Open the word card","title":"In a sentence · precocious","body":"The precocious six-year-old stunned her kindergarten teacher by reading an entire chapter book aloud during free time, then politely asked whether the school library carried any books on ancient Roman architecture.","clip":1},"wh-precocious":{"src":"concept:25:words:0:hook","route":"#/word/precocious","cta":"Open the word card","title":"Remember it · precocious","body":"A precocious child is PRECIOUS but EARLY — precocIOUS, that -ious ending means full of early ripeness."},"wo-precocious":{"src":"lore:precocious:0","route":"#/word/precocious","cta":"Open the word card","title":"Where it comes from · precocious","body":"Latin praecox = ripening before its time"},"wd-precursor":{"src":"concept:25:words:1:def","route":"#/word/precursor","cta":"Open the word card","title":"precursor","roman":"p-r-ee-k-UR-s-ur","body":"a substance from which another substance is formed (especially by a metabolic reaction)","clip":1},"wx-precursor":{"src":"concept:25:words:1:ex","route":"#/word/precursor","cta":"Open the word card","title":"In a sentence · precursor","body":"Scientists discovered that a simple amino acid was the precursor to the complex protein found in muscle tissue.","clip":1},"wh-precursor":{"src":"concept:25:words:1:hook","route":"#/word/precursor","cta":"Open the word card","title":"Remember it · precursor","body":"A precursor RUNS before — like a CURSOR racing ahead on screen"},"wo-precursor":{"src":"lore:precursor:0","route":"#/word/precursor","cta":"Open the word card","title":"Where it comes from · precursor","body":"Latin praecursor = one who runs ahead, from prae (before) + currere (to run)"},"wd-prescient":{"src":"concept:25:words:2:def","route":"#/word/prescient","cta":"Open the word card","title":"prescient","roman":"PREH-see-uhnt","body":"perceiving the significance of events before they occur","clip":1},"wx-prescient":{"src":"concept:25:words:2:ex","route":"#/word/prescient","cta":"Open the word card","title":"In a sentence · prescient","body":"Her prescient warning about the bridge's weak supports was ignored for years before the structure finally collapsed.","clip":1}});
